INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('51195d66-fb10-4745-97b5-58b1eb1b3dd4', 'Full Downward Dog Yoga Pose', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Hamstrings","Shoulders"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Secondary activation of your hamstrings, calves, shoulders provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '97651201', '97651201-Full-Downward-Dog-Yoga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Full Downward Dog Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Full Downward Dog Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('51219939-d846-400c-9584-e2059dc469e8', 'Incline Two Arm Extension (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Using an incline changes the angle of resistance for varied muscle recruitment. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '30781201', '30781201-Dumbbell-Incline-Two-Arm-Extension-(female)_Upper-.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Two Arm Extension. 2. Extend through the target joint(s) for Dumbbell Incline Two Arm Extension. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'arm_exercise', 'Incline Two Arm Extension', 'bicep_curl, tricep_extension, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5123fa96-8dfa-437b-9ffb-b0f978f46ad8', 'Single Rack Pistol Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes provides additional muscle engagement. The kettlebell grip position adds a unique training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '98451201', '98451201-Kettlebell-Single-Rack-Pistol-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Rack Pistol Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'pistol_squat', 'Single Rack Pistol Squat', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('512bccbc-db64-4cc2-8c36-3cbf47fe08cf', 'Lotus Pose Breathing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lotus Pose Breathing is a flexibility exercise that targets your hips, helping to release tension and improve range of motion. Your adductors work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '58851201', '58851201-Lotus-Pose-Breathing-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Move into the stretch position for Lotus Pose Breathing. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'breathing', 'Lotus Pose Breathing', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('512f3342-19b6-4c1a-80d3-075bb0a93c2f', 'Push Jumping Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Your shoulders, calves work as secondary movers, adding to the training stimulus. Regular cardio training builds the aerobic base for better overall fitness. Control the negative portion for maximum muscle engagement.', '51131201', '51131201-Push-Jumping-Jack-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Push Jumping Jack. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'jumping_jack', 'Push Jumping Jack', 'burpee, high_knees, jump_rope', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('514622fb-78f2-4190-8d0e-a2bb348eea4f', 'Squat And Double Knee To Elbow', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat And Double Knee To Elbow is an explosive exercise that combines cardiovascular training with dynamic squatting movements. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '74931201', '74931201-Squat-and-Double-Knee-To-Elbow-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. A solid choice for plyometrics day.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'leg_raise', 'Squat And Double Knee To Elbow', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('514a13e2-6fed-4336-bfd7-c7d1801cebaf', 'Sumo Squat With Heel Raise', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '87051201', '87051201-Sumo-Squat-with-Heel-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Raise the weight in the prescribed direction for Sumo Squat With Heel Raise. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'calf_raise', 'Sumo Squat With Heel Raise', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5153acf4-e56f-4fdd-af29-a79b451b34a0', 'Side Lying Wide Opener', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Side Lying Wide Opener is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '85421201', '85421201-Side-Lying-Wide-Opener-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Lie on your side with your body aligned. 2. Move into the stretch position for Side Lying Wide Opener. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Lying Wide Opener', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('515ad8d0-e4ed-4abb-965c-691026b2759d', 'Overhead Press (Trap Bar)', 'Shoulders', 'Trap Bar', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Trap Bar Overhead Press, an effective shoulder pressing exercise. The triceps assist throughout the movement, making this a well-rounded exercise. Shoulder development enhances both performance and upper body aesthetics.', '72871201', '72871201-Trap-Bar-Overhead-Press-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Start with the weight at shoulder level. 2. Press directly overhead until your arms are fully extended. 3. Lower back to shoulder level with control. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'shoulder_press', 'Overhead Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('51651a1c-31de-4eaa-851a-77ca0cbc4788', 'Lying Figure 4 With Rotation', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your glutes, the Lying Figure 4 With Rotation helps improve mobility and prevent stiffness. Your hips work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '81451201', '81451201-Lying-Figure-4-with-Rotation-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Figure 4 With Rotation. 2. Rotate your torso through the movement pattern for Lying Figure 4 With Rotation. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Figure 4 With Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('516e1c9c-c737-4bd0-9653-fd6da19da9e3', 'Variable Press (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. The dumbbell variation provides freedom of movement and greater range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '98121201', '98121201-Dumbbell-Variable-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Variable Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Variable Press', 'plank, crunch, leg_raise', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('518df31f-f09e-425a-8d90-6f218935dfb1', 'Incline Y Raise Wrist Straps With Back Support (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Cable Incline Y Raise Wrist Straps With Back Suppo is a raising exercise that targets your delts for shoulder development. Secondary activation of your upper back provides additional muscle engagement. Using an incline changes the angle of resistance for varied muscle recruitment. The cable setup allows you to adjust the angle of resistance. Shoulder development enhances both performance and upper body aesthetics.', '86631201', '86631201-Cable-Incline-Y-Raise-Wrist-Straps-with-Back-Suppo.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Y Raise Wrist Straps With Back Suppo. 2. Raise the weight in the prescribed direction for Cable Incline Y Raise Wrist Straps With Back Suppo. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Y Raise Wrist Straps With Back Support', 'shoulder_press, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('51907bc3-2e6d-4fd3-a17f-ef5bbaf14870', 'Kneeling Elbow To Knee Side Plank Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Kneeling Elbow To Knee Side Plank Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '71251201', '71251201-Kneeling-Elbow-to-Knee-Side-Plank-Crunch-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Kneeling Elbow To Knee Side Plank Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('51911833-d03c-466a-920d-96e22b6db670', 'Standing Top Corner Punch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Your shoulders work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '68821201', '68821201-Standing-Top-Corner-Punch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Top Corner Punch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Top Corner Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5193eb12-fb59-407c-aa7b-69680ef1307a', 'Diagonal In Out (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Building core stability helps with everything from heavy deadlifts to daily activities. A staple exercise that belongs in most training programs.', '66351201', '66351201-Diagonal-In-Out-on-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Diagonal In Out On Chair. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Diagonal In Out On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('51b1497c-e432-4d8d-9369-064050567b81', 'Seated Cat Cow Stretch (Chair)', 'Back', 'Chair', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Seated Cat Cow Stretch On A Chair provides a deep stretch for your spine, ideal for recovery and mobility work. Your core work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '91241201', '91241201-Sitting-Cat-Cow-Stretch-on-a-Chair-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Cat Cow Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Cat Cow Stretch On A Chair', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('51b4bfb8-c69c-4c22-92fc-312e98a31689', 'Crunch (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Suspender Crunch is a core crunching exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '11121201', '11121201-Suspender-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'crunch', 'Suspender Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('51bd0117-dd0c-41a8-9659-bfe0834c160e', 'Standing Bike And Opposite Touches', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55091201', '55091201-Standing-Bike-and-Opposite-Touches_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Bike And Opposite Touches. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 52, 9, 8, FALSE, TRUE, 'cycling', 'Standing Bike And Opposite Touches', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('51c052c0-0c78-4ac1-8fc9-c2db39f2f567', 'Kneeling Straight Leg Kickback (left)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. You''ll also feel your hamstrings working to support the movement. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '62091201', '62091201-Kneeling-Straight-Leg-Kickback-(VERSION-2)-(left)_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Kneeling Straight Leg Kickback', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('51c82a06-7327-427c-bdd9-b6e4f95f86ed', 'Standing Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Standing Russian Twist is an explosive exercise that combines cardiovascular training with dynamic twisting movements. You''ll also feel your abs working to support the movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '83921201', '83921201-Standing-Russian-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Russian Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('51cd3488-51c2-473f-b3cc-da4cda4fcd42', 'Depth Jump (Plyo Box)', 'Legs', 'Plyo Box', '{"Quads"}'::text[], '{"Glutes","Hamstrings","Calves"}'::text[], 'The Depth Jump is an explosive exercise that combines cardiovascular training with dynamic jumping movements. Your quads, calves work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '48441201', '48441201-Depth-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Set up in the starting position for Depth Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'box_jump', 'Depth Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('51d6dfbd-b8c1-4d61-9d00-6d72dc17b956', 'Assault Run', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Maintain proper breathing - exhale during the effort phase.', '42291201', '42291201-Assault-Run_Cardio_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set up in the starting position for Assault Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Assault Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('51dc9fdd-708a-42c2-ae0d-2564b9a6fc1f', 'Burpee Press (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Chest","Quads","Core"}'::text[], 'A challenging plyometric exercise, the Dumbbell Burpee Press builds reactive power and improves conditioning. Your chest, quads work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Great for improving athletic performance, burning calories, and building conditioning.', '103821201', '103821201-Dumbbell-Burpee-Press-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Burpee Press. 2. Execute the pressing motion for Dumbbell Burpee Press, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 82, 9, 8, TRUE, TRUE, 'burpee', 'Burpee Press', 'mountain_climber, box_jump, jumping_jack', FALSE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('51e633d2-c6e2-4aed-a5ef-602c48cb8bef', 'Shifting Reverse Lunge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96371201', '96371201-Bodyweight-Shifting-Reverse-Lunge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Shifting Reverse Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('51f976c0-32ab-417a-a359-ba16780a7a97', 'Half Kneeling Face Pull (Resistance Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'This pulling exercise works your delts for improved shoulder strength and aesthetics. The upper back, rotator cuff assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. The band creates increasing tension as it stretches, challenging the lockout. Shoulder development enhances both performance and upper body aesthetics.', '41951201', '41951201-Resistance-Band-Half-Kneeling-Face-Pull_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Secure the resistance band appropriately for Resistance Band Half Kneeling Face Pull. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Pull the rope toward your face, separating your hands as you pull. 4. Squeeze your rear delts and upper back at peak contraction. 5. Return with control, maintaining cable tension. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'face_pull', 'Half Kneeling Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('51f9cf9b-0649-485c-884b-c5efa4848cde', 'Triceps Press (Head Below Bench)', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. Arm strength supports grip, pulling, and pushing in compound movements.', '11911201', '11911201-Triceps-Press-(Head-Below-Bench)_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Triceps Press', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('51fa210a-a026-46ba-a294-1553dba545bc', 'Side Plank March', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Side Plank March, focusing on your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '75421201', '75421201-Side-Plank-March-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('51ffa547-ecda-4de4-b66d-b087f9620597', 'Seated Foot Eversion (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement movement focuses on your gastrocnemius and soleus. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '67451201', '67451201-Cable-Seated-Foot-Eversion-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Foot Eversion. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Foot Eversion', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('520c3878-1ee8-4274-9e1c-44d524a9595f', 'Heel Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength. Start with lighter weight to master the movement pattern.', '66571201', '66571201-Heel-Glute-Bridge-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Heel Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('520d84c5-8ffe-4761-9b75-deb99831bf2b', 'Push And Rotate', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '53591201', '53591201-Push-and-Rotate-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Push And Rotate. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Push And Rotate', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('52114dcc-7e80-452f-9691-45c2d654066a', 'Rear Delt Row (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your upper back provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. A strong back improves posture, prevents injury, and balances pressing movements.', '45361201', '45361201-Kettlebell-Rear-Delt-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Rear Delt Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'rear_delt', 'Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('521a3183-fb0c-4fce-9db1-46df72b419a8', 'Standing Abdominal Vacuum', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '69201201', '69201201-Standing-Abdominal-Vacuum-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Abdominal Vacuum. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Abdominal Vacuum', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('522d198f-42f9-4c5d-bf3f-aa483bbb4f6f', 'Calf Raise Internal External Arms Rotation', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '95191201', '95191201-Calf-Raise-Internal-External-Arms-Rotation-(female.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Rotate your torso through the movement pattern for Calf Raise Internal External Arms Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Raise Internal External Arms Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5236083b-2774-41f3-a7aa-40d6c3ea9be2', 'Seated Calf Rock (Chair)', 'Legs', 'Chair', '{"Calves"}'::text[], '{}'::text[], 'The Seated Calf Rock On A Chair isolates your calf muscles through a movement motion. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '82811201', '82811201-Seated-Calf-Rock-on-a-Chair-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 37, 5, 7, FALSE, TRUE, 'calf_raise', 'Seated Calf Rock On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('523bb0f2-a22e-4806-90b7-16ade17ec66e', 'Arm Ups (Stability Ball) - Alternating', 'Back', 'Stability Ball', '{"Upper Back"}'::text[], '{"Core"}'::text[], 'The Exercise Ball Alternating Arm Ups is a movement exercise that builds thickness in your upper back. Secondary activation of your core provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Back development is crucial for pulling strength and overall upper body function.', '13321201', '13321201-Exercise-Ball-Alternating-Arm-Ups_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Position the stability ball as needed for Exercise Ball Alternating Arm Ups. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'arm_exercise', 'Exercise Ball Arm Ups - Alternating', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('523ec82c-8553-4921-a140-56ad996f01a1', 'Seated Toe Tapping Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '92711201', '92711201-Sitting-Toe-Tapping-Stretch-on-a-Chair-(female)_St.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Toe Tapping Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Toe Tapping Stretch On A Chair', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('524b51ac-5f9b-4042-a93a-83665b79d43d', 'Standing Wide Leg Adductor Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Standing Wide Leg Adductor Stretch is a lower body stretching exercise that targets your adductors. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '19041201', '19041201-Standing-Wide-Leg-Adductor-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Wide Leg Adductor Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'hip_adduction', 'Standing Wide Leg Adductor Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5251d330-9221-49ba-acbe-d74a8ae56959', 'Abdominal Rollout With Pillow (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Your lats, shoulders work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. Core strength is foundational for athletic performance and injury prevention.', '99451201', '99451201-Suspender-Abdominal-Rollout-with-Pillow-(female)_W.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Abdominal Rollout With Pillow. 2. Set up in the starting position for Suspender Abdominal Rollout With Pillow. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 10, 7, 8, TRUE, TRUE, 'ab_rollout', 'Suspender Abdominal Rollout With Pillow', 'plank, crunch, dead_bug', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5258a764-9c05-45a3-b58d-6021b7d4c4f3', 'Assisted Dip (Band)', 'Chest', 'Resistance Band', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger back with this dipping movement targeting your chest. Your triceps, front delts work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. A strong back improves posture, prevents injury, and balances pressing movements.', '42051201', '42051201-Band-Assisted-Dip_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Secure the resistance band appropriately for Band Assisted Dip. 2. Lower your body by bending your elbows to about 90 degrees. 3. Push back up until your arms are fully extended. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'dip', 'Assisted Dip', 'bench_press, tricep_pushdown, push_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('526d3165-9b34-44b6-8a5c-7edb0d8b07f9', 'Figure 8 Swing (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Core","Glutes"}'::text[], 'The Kettlebell Figure 8 Swing is a lower body swinging exercise that targets your full body. You''ll also feel your core, glutes working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '75441201', '75441201-Kettlebell-Figure-8-Swing-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Select an appropriately weighted kettlebell for Kettlebell Figure 8 Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Figure 8 Swing', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('527a51ff-de6d-4f19-965b-c1678bac059e', 'Incline Bench Press (Band)', 'Chest', 'Resistance Band, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Band Incline Bench Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. The band creates increasing tension as it stretches, challenging the lockout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '68451201', '68451201-Band-Incline-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Secure the resistance band appropriately for Band Incline Bench Press. 2. Set the bench to an incline angle (30-45 degrees). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 93, 7, 8, TRUE, TRUE, 'incline_press', 'Incline Bench Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('52cb6308-2f6f-406a-8724-68daa3a30322', 'Lying Overhead Arm Extension', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'The Lying Overhead Arm Extension targets your triceps through a extension motion. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '89981201', '89981201-Lying-Overhead-Arm-Extension-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Overhead Arm Extension. 2. Extend through the target joint(s) for Lying Overhead Arm Extension. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'arm_exercise', 'Lying Overhead Arm Extension', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('52e3bde8-6f9a-4fc0-9c60-154507917305', 'Single Arm Chest Press (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '11241201', '11241201-Suspender-One-Arm-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender One Arm Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'bench_press', 'Suspender Single Arm Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('52e3faab-d2a4-4800-aafa-8e24b746bb07', 'Standing Jab (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'A challenging plyometric exercise, the Cable Standing Jab builds reactive power and improves conditioning. Your shoulders, core work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. The cable setup allows you to adjust the angle of resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '89001201', '89001201-Cable-Standing-Jab-(VERSION-2)-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Jab. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'boxing', 'Standing Jab', 'core_exercise, shoulder_exercise, burpee', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('52ee9045-0adc-4274-b11a-7fc1f6a32472', 'Lying Upper Body Superman Row', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Lying Upper Body Superman Row is a rowing exercise that builds thickness in your upper back. Your glutes work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. A strong back improves posture, prevents injury, and balances pressing movements.', '96681201', '96681201-Lying-Upper-Body-Superman-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Lie down in the appropriate position for Lying Upper Body Superman Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'back_extension', 'Lying Upper Body Superman Row', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('52f2f2b1-f51f-4b2f-be7a-d8126191cb48', 'Two Ropes Climb', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Biceps","Forearms"}'::text[], 'Build lat width and pulling strength with this climbing movement. You''ll also feel your biceps, grip working to support the movement. A strong back improves posture, prevents injury, and balances pressing movements.', '104391201', '104391201-Two-Ropes-Climb_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Set up in the starting position for Two Ropes Climb. 2. Execute the movement with proper form, focusing on your lats. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Two Ropes Climb', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('52f8e6b1-3375-4ab5-9d94-3be49c5498ad', 'Half Sissy Squat (Wall Supported)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '85371201', '85371201-Bodyweight-Half-Sissy-Squat-Wall-Supported-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself at the appropriate distance from a wall. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Maintain a neutral spine throughout. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'squat', 'Half Sissy Squat Wall Supported', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5303555b-b46e-46ee-a8ee-299d15ea9d36', 'Twist Crunch (legs Up)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'The Twist Crunch (legs Up) targets your obliques through a crunching motion, building rotational core strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '55141201', '55141201-Twist-Crunch-(Legs-Up)-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. An effective movement for your core routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Twist Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5305267c-cca2-44d5-a8fc-586ae6939c3f', 'Side Lying Single Arm Lateral Raise (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This stretch specifically works on your lateral delts, promoting flexibility and reducing muscle tightness. The lying position provides back support and helps isolate the target muscles. The cable setup allows you to adjust the angle of resistance. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '94911201', '94911201-Cable-Side-Lying-Single-Arm-Lateral-Raise-(male)_S.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Adjust the cable machine to the correct height and attachment for Cable Side Lying Single Arm Lateral Raise. 2. Lie on your side with your body aligned. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'lateral_raise', 'Side Lying Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5309608f-0387-4c6d-b898-db6c1615417e', 'Shoulder Press (Smith Machine)', 'Shoulders', 'Smith Machine', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Smith Shoulder Press is a pressing exercise that targets your delts for shoulder development. You''ll also feel your triceps working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Strong shoulders improve overhead strength and support nearly all upper body movements.', '7661201', '07661201-Smith-Shoulder-Press_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Shoulder Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'shoulder_press', 'Smith Shoulder Press', 'Shoulder Press', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('5318c8fc-567f-42cf-b702-ab6977d0b9f9', 'Weighted Standing Hand Squeeze', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Weighted Standing Hand Squeeze is an arm movement exercise targeting your full body. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '8541201', '08541201-Weighted-Standing-Hand-Squeeze_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Weighted Standing Hand Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Weighted Standing Hand Squeeze', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5326f414-2f2e-4894-a39a-675f0813ae7f', 'Warm Up Shoulder Stretch (Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{}'::text[], 'This stretching exercise focuses on your pectorals for improved chest strength and development. The band creates increasing tension as it stretches, challenging the lockout. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '45161201', '45161201-Band-Warm-up-Shoulder-Stretch-(male)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Secure the resistance band appropriately for Band Warm Up Shoulder Stretch. 2. Set up in the starting position for Band Warm Up Shoulder Stretch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, 'Pull', 'Isolation', 'Unilateral', NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, 'Neutral', 'Standard', 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 45, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Warm Up Shoulder Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('53288432-cc43-4700-82a7-7ac65ccceaf9', 'Bridge Yoga Pose Setu Bandha Sarv (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Resistance Band Bridge Yoga Pose Setu Bandha Sarv is a hip-dominant bridging exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '103981201', '103981201-Resistance-Band-Bridge-Yoga-Pose-Setu-Bandha-Sarv.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Secure the resistance band appropriately for Resistance Band Bridge Yoga Pose Setu Bandha Sarv. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Bridge Yoga Pose Setu Bandha Sarv', 'stretch_hip, stretch_back, plank', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('5329fdfc-b31f-4843-87ae-99e25e8def2a', 'Squat (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '10041201', '10041201-Band-squat_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Secure the resistance band appropriately for Band Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('53334455-8a24-413d-9089-1604e55fef1c', 'V Up Down (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The V Up Down (stability Ball) is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. The stability ball adds an instability challenge that activates more stabilizer muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '28161201', '28161201-V-Up-Down-(with-Stability-ball)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Position the stability ball as needed for V Up Down. 2. Set up in the starting position for V Up Down. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'v_up', 'V Up Down', 'squat, bench_press, deadlift', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('53346bbf-5e95-4747-b1b6-0604739aaf10', 'Lat Pulldown - Reverse Grip (Machine)', 'Back', 'Machine', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '6731201', '06731201-reverse-grip-machine-lat-pulldown_Back.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Reverse Grip Machine Lat Pulldown. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lat Pulldown - Reverse Grip', 'Lat Pulldown - Reverse Grip', TRUE, 'machine', FALSE, 3, 90, 4, 85, 88, 30, 92),
('5347354d-eabf-46f0-87af-1c886df146f9', 'Kneeling Shoulder Tap Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build power and athleticism with this high-intensity pushing exercise that challenges your entire body. You''ll also feel your triceps, front delts working to support the movement. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '46581201', '46581201-Kneeling-Shoulder-Tap-Push-up-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Shoulder Tap Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('535b8c4a-b0bc-4d37-bc0f-7cc8f2047ea6', 'Axle Deadlift', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Axle Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '69531201', '69531201-Axle-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout. Perfect for targeting your hamstrings/glutes.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'deadlift', 'Axle Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('535fd076-3fc0-4bb5-8107-3466892f6b32', 'Stationary Arms Throw', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Stationary Arms Throw is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, rear delts working to support the movement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '49421201', '49421201-Stationary-Arms-Throw_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. An effective movement for your back routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'arm_exercise', 'Stationary Arms Throw', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5362f0b0-0b17-47d5-ae85-5fce6ea8111a', 'Side Lying One Hand Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your delts. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '4081201', '04081201-Dumbbell-Side-Lying-One-Hand-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lying One Hand Raise. 2. Lie on your side with your body aligned. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Side Lying One Hand Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('53813332-aec5-4ff5-9fc7-6b425aa090f5', 'Twisting Knee Thrust', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Twisting Knee Thrust is an explosive exercise that combines cardiovascular training with dynamic twisting movements. You''ll also feel your abs working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '45491201', '45491201-Twisting-Knee-Thrust_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. Include this in your plyometrics training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 42, 5, 7, FALSE, TRUE, 'knee_drive', 'Twisting Knee Thrust', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('539190df-917d-40b0-9703-a06b0161c421', 'Glute Bridge Two Legs On Floor', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Two Legs On Floor is a hip-dominant bridging exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '24711201', '24711201-Glute-Bridge-Two-Legs-on-Floor-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Position yourself on the floor for Glute Bridge Two Legs On Floor. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Two Legs On Floor', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5393e58a-beb1-43be-98c1-e81543a43763', 'Lying Single Arm Supinated Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Lying One Arm Supinated Triceps Extension targets your triceps through a extension motion. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '3461201', '03461201-Dumbbell-Lying-One-Arm-Supinated-Triceps-Extension_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lie down in the appropriate position for Dumbbell Lying One Arm Supinated Triceps Extension. 3. Use an underhand (supinated) grip with palms facing up/toward you. 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Single Arm Supinated Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('53aa964c-617a-4032-a30d-10b38404faa4', 'Windmill (Kettlebell)', 'Core', 'Kettlebell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Kettlebell Windmill, focusing on your abs. The kettlebell''s offset center of mass increases the stability challenge. A strong core improves posture, protects your spine, and enhances all other lifts.', '5541201', '05541201-Kettlebell-Windmill_waist.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Select an appropriately weighted kettlebell for Kettlebell Windmill. 2. Set up in the starting position for Kettlebell Windmill. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'windmill', 'Windmill', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('53b679c8-f164-4cbc-90c1-310492bbec6e', 'Lying Hip Abduction Knee Bent - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Lying Alternate Hip Abduction Knee Bent is a lower body movement exercise that targets your hip abductors. You''ll also feel your glutes working to support the movement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '84401201', '84401201-Lying-Alternate-Hip-Abduction-Knee-Bent-(female)_H.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Hip Abduction Knee Bent. 2. Alternate between sides/arms/legs with each repetition. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Hip Abduction Knee Bent - Alternating', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('53dd7a02-ea67-40cc-9fde-c1b759794e08', 'Decline Seated Row - Wide Grip (Cable)', 'Back', 'Cables', '{"Upper Back","Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Decline Seated Wide Grip Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '1591201', '01591201-Cable-Decline-Seated-Wide-grip-Row_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the cable machine to the correct height and attachment for Cable Decline Seated Wide Grip Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Repeat for the prescribed number of repetitions.', 'Row', 'Pull', NULL, 'Bilateral', NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'cable_row', 'Decline Seated Row - Wide Grip', 'Decline Seated Row - Wide Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('53e42f3c-cc4f-4e1c-8c77-090b35153b4c', 'Standing Single Leg Calf Raise (Dumbbell)', 'Legs', 'Dumbbells', '{"Calves"}'::text[], '{}'::text[], 'The Dumbbell Standing Single Leg Calf Raise isolates your calf muscles through a raising motion. The standing position engages your core for stability. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '57251201', '57251201-Dumbbell-Standing-Single-Leg-Calf-Raise-(female)_C.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Stand with feet about shoulder-width apart. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 89, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Single Leg Calf Raise', 'calf_raise, seated_calf_raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('53f0f59b-73d3-4de8-9c82-41c2032c8a64', 'Side Step Diagonal Punches', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Diagonal Punches is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Secondary activation of your shoulders provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '77421201', '77421201-Side-Step-Diagonal-Punches-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Diagonal Punches. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Diagonal Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('53f51002-40c7-423f-adc8-891ad9346dcc', 'Stand To Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '85531201', '85531201-Stand-to-Squat-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Stand To Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5403d00c-06cd-4e7a-b0c7-5ceabf9f0a0d', 'Suspended Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '8091201', '08091201-Suspended-Split-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. Beneficial for overall legs development.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Suspended Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('54043307-45ab-4618-a08a-3d25f3c9616f', 'Donkey Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'The Donkey Calf Raise isolates your calf muscles through a raising motion. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '2841201', '02841201-Donkey-Calf-Raise_Calves.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Lower your heels below the platform to get a full stretch. 2. Rise up onto your toes as high as possible, squeezing your calves. 3. Lower with control and repeat. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Donkey Calf Raise', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('540906b1-46d2-44ef-99d8-c827becd9ea5', 'Hawaian Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '33651201', '33651201-Hawaian-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on the mind-muscle connection. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Hawaian Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('540fc37f-cbbe-4f38-a177-6b56950756ae', 'Single Arm Low Row - Rope (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, rear delts provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '104371201', '104371201-Cable-Single-Arm-Low-Row-with-Rope-Attachment_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set the cable pulley to the lowest position and attach your preferred handle. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm Low Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('54162aab-e718-485a-9e0f-132b3d244e69', 'Romanian Deadlift - Staggered Stance (Smith Machine)', 'Legs', 'Smith Machine', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Strengthen the back of your thighs with this hip hinge exercise. Secondary activation of your glutes, lower back provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '88001201', '88001201-Smith-Staggered-Stance-Romanian-Deadlift-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Staggered Stance Romanian Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Smith Staggered Stance Romanian Deadlift', 'Staggered Stance Romanian Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('541657e1-4808-48e2-b2de-6f01c6f14af8', 'Reverse Wrist Curl (Band)', 'Arms', 'Resistance Band', '{"Forearms"}'::text[], '{}'::text[], 'The Band Reverse Wrist Curl strengthens your forearms and grip through a curling motion. The forearms assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Dedicated arm training builds both strength and muscular definition.', '9941201', '09941201-Band-Reverse-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Secure the resistance band appropriately for Band Reverse Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'wrist_curl', 'Reverse Wrist Curl', 'hammer_curl, wrist_curl, bicep_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('5417bee3-6090-44b3-892f-c9e017a9f480', 'Leg Extension Plank', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{}'::text[], 'This extension exercise engages your quads for improved core stability and strength. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '43861201', '43861201-Leg-Extension-Plank_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Extend your legs until straight, squeezing your quads at the top. 2. Lower with control back to the starting position. 3. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_extension', 'Leg Extension Plank', 'squat, leg_press, lunge', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('541848e8-d045-455a-8d89-c3ca0e95d0fe', 'Chest Fly And Press Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Chest Fly And Press Up is a pressing exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '88121201', '88121201-Chest-Fly-and-Press-Up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout. Works well for chest activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly And Press Up', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5420e639-4177-4294-8773-47e079313b23', 'Side Plank Knee Tuck', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Side Plank Knee Tuck, focusing on your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '68521201', '68521201-Side-Plank-Knee-Tuck-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Knee Tuck', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('542a925b-a875-43c5-9c10-9ae26aada015', 'Marching On Spot Press', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Hip Flexors"}'::text[], 'The Marching On Spot Press is an explosive exercise that combines cardiovascular training with dynamic pressing movements. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '55331201', '55331201-Marching-on-Spot-Press_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Execute the pressing motion for Marching On Spot Press, extending through the target muscles. 2. Set up in the starting position for Marching On Spot Press. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'marching', 'Marching On Spot Press', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5436c5f6-5526-4ddf-a849-3b8a05628465', 'Deadlift (Band)', 'Back', 'Resistance Band', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. The glutes, lower back assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '8951201', '08951201-Band-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'deadlift', 'Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('543b8015-a822-475c-a088-aebe4bfc2302', 'Reverse Single Arm Curl (Cable)', 'Arms', 'Cables', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition.', '14131201', '14131201-Cable-Reverse-One-Arm-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse One Arm Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'bicep_curl', 'Reverse Single Arm Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('543d3d75-1289-45f6-aa13-e511230d5e56', 'Seated Chest Opener Cat Cow Pose', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Seated Chest Opener Cat Cow Pose provides a deep stretch for your spine, ideal for recovery and mobility work. Secondary activation of your core provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '90771201', '90771201-Sitting-Chest-Opener-Cat-Cow-Pose-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Chest Opener Cat Cow Pose. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'chest_stretch', 'Seated Chest Opener Cat Cow Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('54405ef7-8ddc-42b0-9b99-3b1862a28418', 'Seated Leg Lift', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads"}'::text[], 'Build leg strength with this movement movement focusing on your hip flexors. Your quads work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Leg training boosts metabolism and builds functional, real-world strength.', '81121201', '81121201-Sitting-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Leg Lift. 3. Execute the movement with proper form, focusing on your hip flexors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Seated Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5444dee2-06e3-44af-a0dd-f44b4be4364f', 'Standing Single Leg Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Standing Single Leg Front Raise is a lower body raising exercise that targets your front delts. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '102051201', '102051201-Standing-Single-Leg-Front-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Complete all reps on one side, then switch to the other side. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'front_raise', 'Standing Single Leg Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('54451608-a45e-41ad-942f-97c4aebec670', 'Bent Over Flexion Row - Back (Barbell)', 'Back', 'Barbell', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your biceps, rear delts working to support the movement. The bent over position requires core engagement to maintain a neutral spine. Using a barbell provides stability for progressive overload. A strong back improves posture, prevents injury, and balances pressing movements.', '106031201', '106031201-Barbell-Bent-Over-Flexion-Row-(back)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Grip a barbell with hands at the appropriate width for Barbell Bent Over Flexion Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 74, 7, 9, TRUE, FALSE, 'back_exercise', 'Bent Over Flexion Row', 'lat_pulldown, pull_up, bicep_curl, face_pull, seated_row', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('54613c50-61a5-452f-9f17-8e6949825fa2', 'Bent Leg 45 Degree Extension (Hyperextension Bench) - Alternating', 'Legs', 'Hyperextension Bench', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build a stronger core with the Alternate Bent Leg 45 Degree Extension, focusing on your quads. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '73911201', '73911201-Alternate-Bent-Leg-45-degree-extension-(male)_Wais.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Extend your legs until straight, squeezing your quads at the top. 2. Lower with control back to the starting position. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_exercise', 'Bent Leg 45 Degree Extension - Alternating', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('546bd026-b769-4841-a9cb-0c5ecf7dc0d2', 'Kneeling Hip Flexor', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{}'::text[], 'Use this stretch to open up your hip flexors area and enhance overall flexibility. The kneeling position adds a core stability challenge. Flexibility work like this enhances performance and prevents stiffness.', '5601201', '05601201-Kneeling-Hip-Flexor-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('546d61ed-3de6-4362-9a66-a3e56e2fa00c', 'Chest Lift With Rotation', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'The Chest Lift With Rotation provides a deep stretch for your chest, ideal for recovery and mobility work. Your shoulders work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '28391201', '28391201-Chest-Lift-with-Rotation_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Rotate your torso through the movement pattern for Chest Lift With Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Chest Lift With Rotation. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_exercise', 'Chest Lift With Rotation', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('547ee4fa-0df7-4ae0-a91f-745b635bcb59', 'Kneeling Knee Tap To Crossed Reach', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'A challenging plyometric exercise, the Kneeling Knee Tap To Crossed Reach builds reactive power and improves conditioning. Your shoulders, core work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '103621201', '103621201-Kneeling-Knee-Tap-to-Crossed-Reach-(male)_Stretch.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Knee Tap To Crossed Reach. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Kneeling Knee Tap To Crossed Reach', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5481db1a-a255-40af-aaf7-ca60b0a00c2e', 'V Flutter Kick', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the V Flutter Kick, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '89931201', '89931201-V-Flutter-Kick-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Set up in the starting position for V Flutter Kick. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'V Flutter Kick', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('54876a1f-faa9-4ecf-bf8e-a72d27cfce5d', 'Kneeling Pulldown (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Band Kneeling Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '9051201', '09051201-Band-Kneeling-Pulldown-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Kneeling Pulldown. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Kneeling Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('54a37a18-d79d-4a75-9e0a-957aec62be2e', 'Single Arm High Row With Chest Support (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '75871201', '75871201-Cable-Single-Arm-High-Row-with-Chest-Support_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'cable_row', 'Single Arm High Row With Chest Support', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('54b62396-fb36-4e2f-8689-7d0c9dd278fe', 'Abdominal Leg Raise - Banded (Machine)', 'Core', 'Machine', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Core strength is foundational for athletic performance and injury prevention.', '65091201', '65091201-Lever-Banded-Abdominal-Leg-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Secure the resistance band appropriately for Lever Banded Abdominal Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'leg_raise', 'Lever Banded Abdominal Leg Raise', 'crunch, plank, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('54b96254-fca3-4aa1-abe4-53fb26d4b9d6', 'Banded Hip Thrust (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '67351201', '67351201-Dumbbell-Banded-Hip-Thrust-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Banded Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'hip_thrust', 'Banded Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('54ba2c0b-cb54-469b-afb6-f910de5c919e', 'Standing Inner Biceps Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Standing Inner Biceps Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '23211201', '23211201-Dumbbell-Standing-Inner-Biceps-Curl-(version-2)_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Inner Biceps Curl. 2. Stand with feet about shoulder-width apart. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Inner Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('54bf3fc3-a889-4325-8ee0-4479168096a8', 'Crunch Bent Knee (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Crunch Bent Knee Against Wall, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '74391201', '74391201-Crunch-Bent-Knee-against-Wall-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Position yourself at the appropriate distance from a wall. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Crunch Bent Knee Against Wall', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('54c85a55-9870-4946-aeb0-b5a731372f59', 'Dolphin Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Dolphin Pose helps improve mobility and prevent stiffness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '62881201', '62881201-Dolphin-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Move into the stretch position for Dolphin Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Dolphin Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('54dacb1d-8a94-49a6-9a29-1abe10ba1192', 'Seated Shoulders Press - Neutral Grip (Kettlebell)', 'Arms', 'Kettlebell', '{"Forearms"}'::text[], '{}'::text[], 'Target your core with the Kettlebell Seated Neutral Grip Shoulders Press, an effective shoulder pressing exercise. The seated position helps isolate the target muscles by removing momentum. The kettlebell grip position adds a unique training stimulus. Strong shoulders improve overhead strength and support nearly all upper body movements.', '68301201', '68301201-Kettlebell-Seated-Neutral-Grip-Shoulders-Press_Sho.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Select an appropriately weighted kettlebell for Kettlebell Seated Neutral Grip Shoulders Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. Start with the weight at shoulder level. 5. Press directly overhead until your arms are fully extended. 6. Lower back to shoulder level with control. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulders Press - Neutral Grip', 'Seated Shoulders Press - Neutral Grip', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('54db8aa4-b1be-4af4-985b-e0ae9265605b', 'Knee Hug Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this stretching movement that emphasizes the glutes. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '63901201', '63901201-Knee-Hug-Glute-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Set up in the starting position for Knee Hug Glute Stretch. 2. Execute the movement with proper form, focusing on your glutes. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'glute_stretch', 'Knee Hug Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('54dbc712-3dd3-4c12-ae89-6e4e5b699372', 'Back Scrub', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Back Scrub is an arm movement exercise targeting your delts. This bodyweight exercise requires no equipment and can be done anywhere. Dedicated arm training builds both strength and muscular definition.', '63751201', '63751201-Back-scrub-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Back Scrub. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Back Scrub', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('54dcbfb8-4ce1-4411-8f62-e5bc75e35895', 'Roll Peroneal (single Leg) Side Lying On Floor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Roll Peroneal (single Leg) Side Lying On Floor is a lower body movement exercise that targets your core. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '53971201', '53971201-Roll-Peroneal-(Single-Leg)-Side-Lying-on-Floor_Cal.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Position yourself on the floor for Roll PeronealSide Lying On Floor. 2. Lie on your side with your body aligned. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'leg_exercise', 'Roll Peroneal Side Lying On Floor', 'Roll Peroneal Side Lying On Floor', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('54e735ec-e1df-4b6b-a3c0-ce845ac6d4da', 'Seated Toes Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Can be modified for beginners or progressed for advanced athletes.', '92691201', '92691201-Sitting-Toes-Stretch-on-a-Chair-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Toes Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Toes Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('54f93b9e-cbe0-42f9-8e0f-5b53a301a241', 'Bulgarian Split Squat (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bulgarian Split Squat With Chair is a squatting exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. Strong legs are the foundation for athletic performance and functional fitness.', '71351201', '71351201-Bulgarian-Split-Squat-with-Chair_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'split_squat', 'Bulgarian Split Squat With Chair', 'split_squat, lunge, leg_press', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('55151410-e9c8-4f80-ae52-5be0eb57ef74', 'Boxing Right Left Hook', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '67271201', '67271201-Boxing-Right-Left-Hook-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Boxing Right Left Hook. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Boxing Right Left Hook', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('551a743d-0e65-4aeb-82b1-eed7e2db7375', 'Side Step Sprinting Arms', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'The Side Step Sprinting Arms is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Great for improving athletic performance, burning calories, and building conditioning.', '90561201', '90561201-Side-Step-Sprinting-Arms-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Sprinting Arms. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'sprint', 'Side Step Sprinting Arms', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5530cf77-4806-4886-a54e-b048a8fdd038', 'Open Book Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Works well as both a primary exercise or accessory movement.', '46011201', '46011201-Open-Book-Stretch_Stretching.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Move into the stretch position for Open Book Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Open Book Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('553c844d-0529-4951-b752-3cca70e4e14f', 'Forward Punch Toe Tap', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. The shoulders assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '56221201', '56221201-Forward-Punch-Toe-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up in the starting position for Forward Punch Toe Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Forward Punch Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5551a85c-5f38-4496-b976-3e607bf19fcd', 'Cross Over Lateral Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Your biceps, upper back work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '30441201', '30441201-Cable-Cross-over-Lateral-Pulldown-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Cross Over Lateral Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Cross Over Lateral Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('5556f614-add2-4de7-b03e-2e30783def1a', 'Incline Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '3301201', '03301201-Dumbbell-Incline-Triceps-Extension_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'tricep_extension', 'Incline Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('55594b96-fd0c-47dd-98aa-b6f34d51d037', 'Side Plank Clamshell', 'Legs', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Hip Abductors"}'::text[], 'The Side Plank Clamshell is a lower body stabilization exercise that targets your glute med/abductors. Your hip abductors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '98491201', '98491201-Side-Plank-Clamshell-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Clamshell', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('555c4d2a-bd18-4556-a422-86067bf027c8', 'Incline Shoulders Press (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Shoulders","Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Using an incline changes the angle of resistance for varied muscle recruitment. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '79241201', '79241201-Dumbbell-Incline-Shoulders-Press-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Shoulders Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Incline Shoulders Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('555d10e3-0c85-4ee3-b2f8-6458efb1c9ec', 'Stationary Bike Run (Stationary Bike)', 'Full Body', 'Stationary Bike', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stationary Bike Run is a cardiovascular exercise that improves endurance and heart health. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Maintain proper breathing - exhale during the effort phase.', '22791201', '22791201-Stationary-Bike-Run-(version-4)_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Set up in the starting position for Stationary Bike Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'cycling', 'Stationary Bike Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('55658910-5244-4ea4-b1bc-ef521e3ba1f7', 'Seated Side Bend (Dumbbell)', 'Core', 'Dumbbells, Flat Bench', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. You''ll also feel your abs working to support the movement. The seated position helps isolate the target muscles by removing momentum. Using dumbbells requires more stabilization than barbell variations. Core strength is foundational for athletic performance and injury prevention.', '69521201', '69521201-Dumbbell-Seated-Side-Bend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Side Bend. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'side_bend', 'Seated Side Bend', 'russian_twist, woodchop, oblique_crunch', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('5571fdce-560b-44bb-bc94-b10bd02d8cce', 'Seated Toe Raise (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lever Seated Toe Raise isolates your calf muscles through a raising motion. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '95091201', '95091201-Lever-Sitting-Toe-Raise-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Toe Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in the prescribed direction for Lever Seated Toe Raise. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'calf_raise', 'Lever Seated Toe Raise', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('5575476e-7975-4f07-9f6f-a66838c8ca12', 'Seated Crunch (Machine)', 'Core', 'Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lever Seated Crunch is a core crunching exercise that primarily targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Core strength is foundational for athletic performance and injury prevention.', '24451201', '24451201-Lever-Seated-Crunch-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Lever Seated Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('5579ec6c-d467-40e8-9248-09438f5f5677', 'Briskly Walking Side', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Keep your core engaged throughout the exercise.', '30031201', '30031201-Briskly-Walking-Side-POV-(female).mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Set up in the starting position for Briskly Walking Side POV. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Briskly Walking Side POV', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('557a3692-0f01-4784-897e-36e4a93e36d3', 'Jack Knife (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Suspender Jack Knife is a core movement exercise that primarily targets your abs. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '10821201', '10821201-Suspender-Jack-knife-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Jack Knife. 2. Set up in the starting position for Suspender Jack Knife. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 40, 9, 8, TRUE, TRUE, 'general_exercise', 'Suspender Jack Knife', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 60, 4, 68, 85, 85, 70),
('557bbc27-ed62-4a50-a7d5-caf5dc609b28', 'Crossover Kneeling Hip Flexor Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Elevate your training with this stretching exercise that develops speed, power, and coordination. The shoulders, core assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '42961201', '42961201-Crossover-Kneeling-Hip-Flexor-Stretch-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Crossover Kneeling Hip Flexor Stretch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Crossover Kneeling Hip Flexor Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('558124ab-36d7-420d-8edc-8731cddfc987', 'Seated Bicep Curl - Single Arm Unilateral (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Seated Single Arm Unilateral Biceps Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '79221201', '79221201-Cable-Seated-Single-Arm-Unilateral-Bicep-Curl_Uppe.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Single Arm Unilateral Biceps Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Single Arm Unilateral Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('558360c5-64fd-477f-acb2-426dbe567844', 'Lateral Raise (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. Cables provide constant tension throughout the full range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '1781201', '01781201-Cable-Lateral-Raise_shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'lateral_raise', 'Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5583e04e-5525-453f-8daa-3d6cfa8953b3', 'Seated Twist (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Cable Seated Twist. You''ll also feel your abs working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '23991201', '23991201-Cable-Seated-Twist_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Cable Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('55854248-f7c7-4028-9770-1e1ef1495664', 'Push Up Row', 'Chest', 'Bodyweight', '{"Back","Lats"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '71171201', '71171201-Push-up-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. A solid choice for back day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up Row', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('558700ba-eda7-48a6-aba7-614ec068f5a3', 'Chop Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '77791201', '77791201-Chop-Knee-Raise-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Raise the weight in the prescribed direction for Chop Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Chop Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5592194b-69f5-4344-a1c2-4243d10dbe0f', 'Weighted Russian Twist (legs Up)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. The abs assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '8451201', '08451201-Weighted-Russian-Twist-(legs-up)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Rotate your torso through the movement pattern for Weighted Russian Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Weighted Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('55b4db9e-0538-4af6-ba5e-e5cda2881218', 'Standing Front And Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Dumbbell Standing Front And Lateral Raise, an effective shoulder raising exercise. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Shoulder development enhances both performance and upper body aesthetics.', '74491201', '74491201-Dumbbell-Standing-Front-and-Lateral-Raise_Shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Front And Lateral Raise. 2. Stand tall with your feet firmly planted. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Front And Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('55cfb7f9-2675-4b82-9b18-b6af88b20e5c', 'Seated Side To Side Neck Twist (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This stretch specifically works on your obliques, promoting flexibility and reducing muscle tightness. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105561201', '105561201-Seated-Side-to-Side-Neck-Twist-on-Chair-(male)_St.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Side To Side Neck Twist On Chair. 4. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 37, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Side To Side Neck Twist On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('55dc07b3-5d36-4aaf-ac7d-a8e8dc63d86b', 'Kneeling Push Up To Child Pose', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Kneeling Push Up To Child Pose, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '32651201', '32651201-Kneeling-Push-up-to-Child-Pose-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Kneeling Push Up To Child Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('55e0fc7d-f9bb-40b0-acd3-2d313bf2e56f', 'Psoas Walk (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this stepping movement focusing on your full body. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '100121201', '100121201-Resistance-Band-Psoas-Walk-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Psoas Walk. 2. Set up in the starting position for Resistance Band Psoas Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'walking', 'Psoas Walk', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('55e7d8a0-37f9-43a9-90f7-fb39823b40ce', 'Deep Prisoner Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs. Consistency with this movement will yield noticeable results.', '85151201', '85151201-Deep-Prisoner-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Deep Prisoner Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('55f7521a-cc3a-4971-8f94-53c94bcd4ea5', 'Hand Overhead Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements. Perfect for including in both strength and hypertrophy programs.', '97091201', '97091201-Hand-Overhead-Circle-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Hand Overhead Circle. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Hand Overhead Circle', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('55fdaa62-d0b7-4b38-9cdb-726948f221e8', 'Standing Front Raise To Open', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Designed to lengthen your front delts, the Bodyweight Standing Front Raise To Open helps improve mobility and prevent stiffness. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '86021201', '86021201-Bodyweight-Standing-Front-Raise-to-Open-(female)_S.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Stand tall with your feet firmly planted. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'front_raise', 'Standing Front Raise To Open', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('55ffe345-df38-46d0-a27f-ffea71adfeaa', 'Lizard Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Focus on controlled form throughout each repetition.', '65181201', '65181201-Lizard-Pose-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Move into the stretch position for Lizard Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'hip_stretch', 'Lizard Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('56175188-4326-404c-95db-c8e528ad89d4', 'Single Leg Floor Calf Raise', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '26251201', '26251201-One-Leg-Floor-Calf-Raise-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Position yourself on the floor for One Leg Floor Calf Raise. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'calf_raise', 'Single Leg Floor Calf Raise', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5619ceb0-0020-4e07-a39d-29374e2279a4', 'Seated Row To Neck - Rope - Neutral Grip (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '106011201', '106011201-Cable-Seated-Neutral-grip-Row-to-Neck-(rope-attac.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Neutral Grip Row To Neck (rope Attac. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'neck_exercise', 'Seated Row To Neck - Neutral Grip', 'Seated Row To Neck - Neutral Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('5624ac30-7f34-4813-95ab-d2546140f0a4', 'Balance Plate Standing Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Balance Plate Standing Twist targets your obliques through a twisting motion, building rotational core strength. You''ll also feel your abs working to support the movement. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '84761201', '84761201-Balance-Plate-Standing-Twist-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Balance Plate Standing Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'balance', 'Balance Plate Standing Twist', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('563773d6-86cd-469c-b69e-053ac78fdc19', 'Lower Ab Swipe', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. Keep your core engaged throughout the exercise.', '78551201', '78551201-Lower-Ab-Swipe-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up in the starting position for Lower Ab Swipe. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'core_exercise', 'Lower Ab Swipe', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('564303cd-4562-41c8-bc96-57b2fb17ce13', 'Goblet Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs. Consistency with this movement will yield noticeable results.', '22811201', '22811201-Dumbbell-Goblet-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'goblet_squat', 'Goblet Squat', 'squat, front_squat, lunge', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('56515229-bc2d-4132-8fa9-1964d87a9a96', 'Side Step Rear Delt Row', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This dynamic rowing movement gets your heart rate up while developing explosive strength. Secondary activation of your upper back provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '60121201', '60121201-Side-Step-Rear-Delt-Row-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'rear_delt', 'Side Step Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5659a12c-9bab-4401-820e-32985ecbf6b4', 'Seated Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Seated Triceps Extension targets your triceps through a extension motion. The seated position helps isolate the target muscles by removing momentum. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '24881201', '24881201-Dumbbell-Seated-Triceps-Extension-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Triceps Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('56653fa9-cdff-4d32-b44b-0cdbeb5112d0', 'Knuckle Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Knuckle Push Up Against Wall is a pushing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. A well-developed chest contributes to upper body strength and aesthetics.', '82751201', '82751201-Knuckle-Push-up-against-Wall-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Knuckle Push Up Against Wall', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('566979cb-a001-417a-9b30-4773319453da', 'Side Squat (TRX)', 'Legs', 'TRX', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Suspender Side Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The TRX allows you to adjust difficulty by changing your body angle. Strong legs are the foundation for athletic performance and functional fitness.', '95061201', '95061201-Suspender-Side-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Side Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'side_bend', 'Suspender Side Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('566d1b02-3e08-4033-947d-f381ce63dee0', 'Weighted Svend Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Weighted Svend Press, an effective pressing movement for upper body strength. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '34261201', '34261201-Weighted-Svend-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squeeze_press', 'Weighted Svend Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56873409-a199-41f3-bc24-756d9327fef5', 'Hamstring Runner (TRX)', 'Legs', 'TRX', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This movement movement works your hamstrings for balanced leg development. Suspension training adds instability, increasing core activation throughout. Strong legs are the foundation for athletic performance and functional fitness.', '10761201', '10761201-Suspender-Hamstring-Runner-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Hamstring Runner. 2. Set up in the starting position for Suspender Hamstring Runner. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 28, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Hamstring Runner', 'cycling, rowing_cardio, jump_rope', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('56899198-6055-4d43-8118-f91107e7948d', 'Woodchops', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Woodchops targets your obliques through a movement motion, building rotational core strength. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '78211201', '78211201-Woodchops-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Set up in the starting position for Woodchops. 2. Execute the movement with proper form, focusing on your obliques. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'woodchop', 'Woodchops', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5693c0db-0f48-412f-aaf2-99556fa7ec47', 'Single Arm Triceps Pushdown - Rope (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This pushing movement isolates your triceps for improved arm development. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '73991201', '73991201-Cable-Single-Arm-Triceps-Pushdown-(rope-attachment.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Single Arm Triceps Pushdown. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 47, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Single Arm Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', TRUE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('569a2159-4661-4fe5-b6f0-c558ab40a074', 'Overhead Forward Lunge (Plate)', 'Legs', 'Weight Plate', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '96101201', '96101201-Weighted-Plate-Overhead-Forward-Lunge-(male)_Thigh.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Weighted Plate Overhead Forward Lunge', 'split_squat, step_up, squat', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('569a281b-dcd7-4dfa-8a88-6bdc43716aa7', 'Self Assisted Inverse Leg Curl', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '68831201', '68831201-Self-Assisted-Inverse-Leg-Curl-(VERSION-3)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'leg_curl', 'Self Assisted Inverse Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56a6cbe2-be04-47fd-ba1f-848adb7a615d', 'Jumping Jack (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{"Shoulders","Calves"}'::text[], 'Build leg strength with this jumping movement focusing on your full body. Secondary activation of your shoulders, calves provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '24651201', '24651201-Resistance-Band-Jumping-Jack-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Jumping Jack. 2. Set up in the starting position for Resistance Band Jumping Jack. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 55, 9, 8, TRUE, TRUE, 'jumping_jack', 'Jumping Jack', 'burpee, high_knees, jump_rope', FALSE, 'band', FALSE, 3, 60, 4, 60, 85, 90, 50),
('56a83bca-883d-4770-afa5-af3bff257576', 'Supported Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. This is a great exercise for all fitness levels with proper scaling.', '47971201', '47971201-Supported-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement. Beneficial for overall legs development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Supported Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56b82d4d-a75a-44e7-bc46-f79531575dc2', 'Lean Forward Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Flexibility work like this enhances performance and prevents stiffness. Can be modified for beginners or progressed for advanced athletes. Consistency with this movement will yield noticeable results.', '56951201', '56951201-Lean-Forward-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Move into the stretch position for Lean Forward Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Lean Forward Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('56bfdce8-0cd9-45e1-a9d6-d4d5b7efcbb8', 'Front Squat - Arms Crossed (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness.', '421201', '00421201-Barbell-Front-Squat_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard (Shoulder-Width)', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 89, 7, 9, TRUE, FALSE, 'front_squat', 'Front Squat', 'squat, leg_press, leg_extension, goblet_squat', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('56c69d7d-406e-426f-be5a-2ff5bbd9500a', 'Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Push Up (wall) is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '26141201', '26141201-Push-up-(wall)-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56d1e1d2-b25d-4192-a109-f1b1fab1610c', 'Pulldown - Reverse Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Your biceps, upper back work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '24911201', '24911201-Cable-Reverse-Grip-Pulldown-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Grip Pulldown. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Pulldown - Reverse Grip', 'Pulldown - Reverse Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('56dca588-3f64-4427-85c9-e87faebff95b', 'Deadlift (Smith Machine)', 'Back', 'Smith Machine', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '36181201', '36181201-Smith-Deadlift-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'deadlift', 'Smith Deadlift', 'Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('56dcb0bd-96d6-4f49-b795-6826082226b6', 'Lying Twist Toe Touch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Lying Twist Toe Touch targets your obliques through a twisting motion, building rotational core strength. Your hip flexors work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '71411201', '71411201-Lying-Twist-Toe-Touch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Lie down in the appropriate position for Lying Twist Toe Touch. 2. Rotate your torso through the movement pattern for Lying Twist Toe Touch. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'toe_touch', 'Lying Twist Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('56ec6f4c-b88a-44bb-a626-6de8bdca0493', 'Weighted Steel Mace Halo', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics. Control the negative portion for maximum muscle engagement.', '104111201', '104111201-Weighted-Steel-Mace-Halo-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set up in the starting position for Weighted Steel Mace Halo. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Weighted Steel Mace Halo', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56ee7839-0ecb-42d7-923e-9edb79b7dcfe', 'Rear Lunge Front Raise', 'Legs', 'Bodyweight', '{"Quads","Glutes","Hamstrings"}'::text[], '{"Chest"}'::text[], 'The Bodyweight Rear Lunge Front Raise is a lunging exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '56421201', '56421201-Bodyweight-Rear-Lunge-Front-Raise-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Raise the weight in front of you to shoulder height. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'front_raise', 'Rear Lunge Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('56fe41cf-d487-4b28-bd2e-9bb4731fb90a', 'Upper Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '13241201', '13241201-Cable-Upper-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Adjust the cable machine to the correct height and attachment for Cable Upper Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'general_exercise', 'Upper Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('56fe88e5-1122-457c-94af-572f6f8b15d8', 'Decline Chest Fly - Twist (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Abs"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. You''ll also feel your abs working to support the movement. Declining shifts the emphasis to hit the muscles from a different angle. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '25851201', '25851201-Dumbbell-Decline-Twist-Fly-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Twist Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', 'Fly', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'russian_twist', 'Decline Twist Fly', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('56ff66fd-fddd-4032-a71e-7c845166bcbd', 'Russian Twist (Kettlebell)', 'Core', 'Kettlebell', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Kettlebell Russian Twist targets your obliques through a twisting motion, building rotational core strength. You''ll also feel your abs working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. A strong core improves posture, protects your spine, and enhances all other lifts.', '43931201', '43931201-Kettlebell-Russian-Twist_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Select an appropriately weighted kettlebell for Kettlebell Russian Twist. 2. Rotate your torso through the movement pattern for Kettlebell Russian Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('57024513-6ade-4921-b546-b002dd03e6e6', 'Seated Heel Slide (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Heel Slide On Chair is a lower body movement exercise that targets your core. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '87451201', '87451201-Seated-Heel-Slide-on-Chair-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Heel Slide On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('570820df-3fd3-42df-b1e8-8fc645b1faff', 'Romanian Deadlift (Cable)', 'Legs', 'Cables', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Cable Romanian Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. Cable resistance creates smooth, continuous muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '82961201', '82961201-Cable-Romanian-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Adjust the cable machine to the correct height and attachment for Cable Romanian Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 95, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('571c7514-9968-45c4-876a-da8a2feba12b', 'Half Pigeon Hip Stretch', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. Perfect for including in both strength and hypertrophy programs. Consistency with this movement will yield noticeable results.', '67611201', '67611201-Half-Pigeon-Hip-Stretch-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Half Pigeon Hip Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Half Pigeon Hip Stretch', 'stretch_hamstring, stretch_glute, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('571f8f5c-4356-4d79-bd45-b59979113d0f', 'Landmine Single Arm Low Fly (Landmine)', 'Chest', 'Landmine Attachment, Barbell', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. You''ll also feel your front delts working to support the movement. A well-developed chest contributes to upper body strength and aesthetics.', '66991201', '66991201-Landmine-Single-Arm-Low-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'chest_fly', 'Landmine Single Arm Low Fly', 'bench_press, incline_press, push_up', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('572558f8-232b-41ed-8fce-537e9d380acd', 'Concentration Curl (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Band Concentration Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '9761201', '09761201-Band-Concentration-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Secure the resistance band appropriately for Band Concentration Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', 'Isolation', 'Unilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, 'Underhand (Supinated)', 'Neutral', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'concentration_curl', 'Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('572a5b34-6903-4594-8a90-2572b84d3929', 'Standing Archer Arm Row (Resistance Band) - Alternating', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '101301201', '101301201-Resistance-Band-Standing-Archer-Alternate-Arm-Row.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Archer Alternate Arm Row. 2. Stand tall with your feet firmly planted. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Alternate between sides/arms/legs with each repetition. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Archer Arm Row - Alternating', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('572b9ff3-9246-4bc6-9e8a-111cca84054d', 'Hands Up Side Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Hands Up Side Step is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Your quads work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '58501201', '58501201-Hands-Up-Side-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Hands Up Side Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Hands Up Side Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('573b2e85-5df2-4f36-ba46-5452d5594ee6', 'Standing Wide Knees Adductor Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this stretching movement focusing on your adductors. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '18941201', '18941201-Standing-Wide-Knees-Adductor-Stretch-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Wide Knees Adductor Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'hip_adduction', 'Standing Wide Knees Adductor Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('573c1968-7e7c-469b-a5a8-915933ea7d8f', 'Seated Calf Stretch (Resistance Band)', 'Legs', 'Resistance Band', '{"Calves"}'::text[], '{}'::text[], 'The Resistance Band Seated Calf Stretch is a flexibility exercise that targets your calves, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Include this in your routine for better mobility and reduced muscle tension.', '54801201', '54801201-Resistance-Band-Seated-Calf-Stretch-(female)_Calve.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Seated Calf Stretch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Resistance Band Seated Calf Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 47, 2, 6, FALSE, TRUE, 'calf_stretch', 'Seated Calf Stretch', 'stretch_hip, stretch_back', FALSE, 'band', TRUE, 1, 30, 2, 60, 85, 90, 50),
('573f912a-deea-46ef-ae5b-436ee48cc880', 'Jack Split Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '5051201', '05051201-Jack-Split-Crunches_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'crunch', 'Jack Split Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('57451014-5428-4b07-9447-db01845be336', 'Preacher Curl - Rope (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Cable Preacher Curl (rope Attachment) is a curling exercise that isolates your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '97421201', '97421201-Cable-Preacher-Curl-(rope-attachment)-(female)_Upp.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection. Include this in your arms training.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'preacher_curl', 'Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('574750ad-d8d4-4d55-9a56-736ae5b8ebad', 'Side Step Pushdown', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This dynamic pushing movement gets your heart rate up while developing explosive strength. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '98361201', '98361201-Side-Step-Pushdown-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Pushdown. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Side Step Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5749733c-5e00-4e2f-a60c-852c08ef4073', 'Kneeling Finger Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Finger Pulse is an arm movement exercise targeting your core. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '69771201', '69771201-Kneeling-Finger-Pulse-(male)_Hands_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pulse', 'Kneeling Finger Pulse', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('574afc97-7561-405c-b76b-36c39e82cbe7', 'Leg Press - Single Leg (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this pressing movement that develops leg drive and power. You''ll also feel your glutes working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '67341201', '67341201-Sled-Angled-Single-Leg-Press-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Complete all reps on one side, then switch to the other side. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 75, 7, 9, TRUE, FALSE, 'leg_press', 'Sled Angled Single Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('574e3f0e-a064-4876-a701-18a280f655ef', 'Side Plank Elbow To Knee Raise', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Build a stronger core with the Side Plank Elbow To Knee Raise, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '104021201', '104021201-Side-Plank-Elbow-to-Knee-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Elbow To Knee Raise', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('5751f52f-74de-478c-8861-34c890d91490', 'Standing Balance Single Leg Lifts Reverse Fly', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Standing Balance Single Leg Lifts Reverse Fly targets your rear deltoids with a flying motion. The upper back assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '87921201', '87921201-Standing-Balance-Single-Leg-Lifts-Reverse-Fly-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'rear_delt', 'Standing Balance Single Leg Lifts Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('57552602-e49f-4d25-9b61-a5d73d47dda9', 'Lying (prone) Abdominal Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying (prone) Abdominal Stretch, focusing on your abs. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '10551201', '10551201-Lying-(prone)-Abdominal-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie face down with your body in a straight line. 2. Set up in the starting position for LyingAbdominal Stretch. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Lying  Abdominal Stretch', 'Lying Abdominal Stretch', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('575b5769-032b-4093-8b1a-b8595165449f', 'Standing Military Press (Wall Supported)', 'Shoulders', 'Wall', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your triceps provides additional muscle engagement. The standing position engages your core for stability. Strong shoulders improve overhead strength and support nearly all upper body movements.', '46131201', '46131201-Bodyweight-Standing-Military-Press-Wall-Supported_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 69, 7, 8, TRUE, TRUE, 'shoulder_press', 'Standing Military Press Wall Supported', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('576242a9-cd4a-45a3-9253-d4128e02f2cf', 'Stepback Front Kick Arms Raise', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. Your quads work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '93651201', '93651201-Stepback-Front-Kick-Arms-Raise-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Stepback Front Kick Arms Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('576d49a4-e5ab-4a9e-8fcd-f57f5f93ed06', 'Weighted Lying Svend Press', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '90331201', '90331201-Weighted-Lying-Svend-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Lie down in the appropriate position for Weighted Lying Svend Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'squeeze_press', 'Weighted Lying Svend Press', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('577bee5d-4cd5-4feb-8d25-cbd2fd9eb30e', 'Side To Side Knee Hugs', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Works well as both a primary exercise or accessory movement.', '79661201', '79661201-Side-to-Side-Knee-Hugs-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Move into the stretch position for Side To Side Knee Hugs. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side To Side Knee Hugs', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('57849fe0-2e0b-4221-a306-b6365373683f', 'Pull Up - Wide Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function. This is a great exercise for all fitness levels with proper scaling.', '6511201', '06511201-Pull-up-(wide-grip)_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('57a7312b-6421-40c0-9c56-41ced8c0f98a', 'Push Up (Bodweight)', 'Chest', 'Bodyweight, Towel', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. The machine guides your movement path for safer, more controlled repetitions. A well-developed chest contributes to upper body strength and aesthetics.', '78841201', '78841201-Lever-Push-up-with-Towels-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Push Up With Towels. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'push_up', 'Lever Push Up With Towels', 'bench_press, chest_fly, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 80, 75, 20, 88),
('57b043f8-2f12-43e2-a115-c5c3d1f28bdf', 'Single Leg Step Up (Dumbbell)', 'Legs', 'Dumbbells, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stepping movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '57561201', '57561201-Dumbbell-Single-Leg-Step-Up-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'step_up', 'Single Leg Step Up', 'lunge, split_squat, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('57c93071-f9cf-4265-8bca-0b6b88462b93', 'Kneeling Straight Leg Kickback', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. You''ll also feel your hamstrings working to support the movement. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '47721201', '47721201-Kneeling-Straight-Leg-Kickback-(VERSION-2)-(female.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Kneeling Straight Leg Kickback', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('57c9b351-499f-49b5-b904-e15e70bb7b26', 'Power Pull (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this pulling movement that works your abs. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '88441201', '88441201-Suspender-Power-Pull-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Power Pull. 2. Perform the concentric (lifting) phase explosively with maximum effort. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Power Pull', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('57d939a1-6c7b-40e8-a597-7a66e1140697', 'Weighted Side Bend - On Stability Ball (Stability Ball)', 'Core', 'Stability Ball', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The abs assist throughout the movement, making this a well-rounded exercise. The stability ball adds an instability challenge that activates more stabilizer muscles. Core strength is foundational for athletic performance and injury prevention.', '8501201', '08501201-Weighted-Side-Bend-(on-stability-ball)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Position the stability ball as needed for Weighted Side Bend. 2. Set up in the starting position for Weighted Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'side_bend', 'Weighted Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('57d9db64-516c-4a7b-99d0-2731d4aebffa', 'Front Raise (TRX)', 'Shoulders', 'TRX', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Suspender Front Raise, an effective shoulder raising exercise. Suspension training adds instability, increasing core activation throughout. Shoulder development enhances both performance and upper body aesthetics.', '10751201', '10751201-Suspender-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'front_raise', 'Suspender Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('57e1d254-2790-4cf2-aae4-ca970fa4f736', 'Elevated Deep Lunge Dorsi Flexion', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Elevanted Deep Lunge Dorsi Flexion is a flexibility exercise that targets your quads, helping to release tension and improve range of motion. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '94621201', '94621201-Elevanted-Deep-Lunge-Dorsi-Flexion-(male)_Stretchi.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Elevanted Deep Lunge Dorsi Flexion. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Elevanted Deep Lunge Dorsi Flexion', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('57f8d173-ffa0-4a38-b0de-6fdacc1fc51e', 'Wide Bench Press - Reverse Grip (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12581201', '12581201-Barbell-Wide-Reverse-Grip-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Wide Bench Press - Reverse Grip', 'Wide Bench Press - Reverse Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('57f9cff1-f992-40a7-873c-8f86fc8c2e6a', 'Arm Crossover Curtsy', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'The Arm Crossover Curtsy is an explosive exercise that combines cardiovascular training with dynamic movement movements. Secondary activation of your front delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '55921201', '55921201-Arm-Crossover-Curtsy-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Set up in the starting position for Arm Crossover Curtsy. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Crossover Curtsy', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('57fa77ab-020e-4a9a-bae2-1d45f84b2c02', 'Spin Back Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic kicking movement gets your heart rate up while developing explosive strength. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '23101201', '23101201-Spin-Back-Kick_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Set up in the starting position for Spin Back Kick. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'cycling', 'Spin Back Kick', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('58025e5f-793b-437b-9857-04f2c266f80b', 'Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Knee Raise is a lower body raising exercise that targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '32521201', '32521201-Knee-Raise-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Raise the weight in the prescribed direction for Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5807fcb5-4996-429e-8fa7-3382a27f4ac9', 'Side To Side Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. Control the negative portion for maximum muscle engagement. Consistency with this movement will yield noticeable results.', '81861201', '81861201-Side-to-Side-Hop-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Set up in the starting position for Side To Side Hop. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Side To Side Hop', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('580b06fa-8db4-4a51-accb-f23dd2e2a097', 'Elbow To Knee Side Plank Crunch (left)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '62101201', '62101201-Elbow-to-Knee-Side-Plank-Crunch-(left)-(female)_Wa.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Elbow To Knee Side Plank Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('580fc013-6e17-43a0-8a2a-3fc0c4ac6829', 'Rope Crossover Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build power and athleticism with this high-intensity rowing exercise that challenges your entire body. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. Plyometric training builds explosive power that transfers to sports and daily activities.', '13201201', '13201201-Cable-Rope-Crossover-Seated-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Adjust the cable machine to the correct height and attachment for Cable Rope Crossover Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Rope Crossover Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('58225e84-299b-4e43-9e3e-842f49efbcf0', 'Lying Knee Tuck - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Alternate Knee Tuck is a lower body movement exercise that targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '81371201', '81371201-Lying-Alternate-Knee-Tuck-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Lie down in the appropriate position for Lying Alternate Knee Tuck. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Knee Tuck - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5836d5b0-d7f2-42e7-aec1-12814c535b0b', 'Seated Neck Flexion To Extension (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This extension exercise engages your core for improved core stability and strength. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '105551201', '105551201-Seated-Neck-Flexion-to-Extension-on-Chair-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend through the target joint(s) for Seated Neck Flexion To Extension On Chair. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'neck_exercise', 'Seated Neck Flexion To Extension On Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('583cc61f-13c8-4e05-a159-64d62fa7c9b0', 'Landmine 180 (Landmine)', 'Core', 'Landmine Attachment, Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Building core stability helps with everything from heavy deadlifts to daily activities. Works well as both a primary exercise or accessory movement.', '36051201', '36051201-Landmine-180-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up in the starting position for Landmine 180. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Landmine 180', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('583eea5f-e71a-47b7-a53b-70aded8b7709', 'Battling Ropes', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'The Battling Ropes is a compound movement exercise that engages your entire body. Secondary activation of your shoulders, core provides additional muscle engagement. Compound movements like this develop coordination, power, and overall fitness.', '25651201', '25651201-Battling-Ropes-(female).mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up in the starting position for Battling Ropes. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Battling Ropes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('5862f38f-6d1c-4095-82e0-7b678cb4e79c', 'Reach Front Reach Top Sumo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'The Reach Front Reach Top Sumo Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '56151201', '56151201-Reach-Front-Reach-Top-Sumo-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Reach Front Reach Top Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('58643658-522e-4a5a-bbdb-a4a96d962d58', 'Seated High Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '79231201', '79231201-Cable-Seated-High-Triceps-Extension_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Seated High Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('587a4aa1-9a6b-4cd7-85f2-b44cc956dbe0', 'Lying Pressdown - Skull Crusher - Reverse Grip (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. The lying position provides back support and helps isolate the target muscles. Bands are joint-friendly and portable, perfect for any training environment. Dedicated arm training builds both strength and muscular definition.', '70441201', '70441201-Band-Lying-Reverse-Grip-Pressdown-(Skull-Crusher)-.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Lying Reverse Grip Pressdown. 2. Lie down in the appropriate position for Band Lying Reverse Grip Pressdown. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Execute the pressing motion for Band Lying Reverse Grip Pressdown, extending through the target muscles. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'tricep_extension', 'Lying Pressdown - Reverse Grip', 'Lying Pressdown - Reverse Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('587a4cea-93b7-45cb-9e90-3e9412180dce', 'Assisted Partial Range Inverse Leg Curl Against Wa', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Assisted Partial Range Inverse Leg Curl Against Wa targets your hamstrings through a controlled curling motion. Your calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '75031201', '75031201-Assisted-Partial-Range-Inverse-Leg-Curl-against-Wa.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'leg_curl', 'Assisted Partial Range Inverse Leg Curl Against Wa', 'romanian_deadlift, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5882dea1-14d0-42d5-ba37-cb88462e1739', 'Standing Interlock Hands Full Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Standing Interlock Hands Full Stretch helps improve mobility and prevent stiffness. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '95591201', '95591201-Standing-Interlock-Hands-Full-Stretch-(female)_Str.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Interlock Hands Full Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 27, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Interlock Hands Full Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5892a0bf-c145-43d2-9c94-b0f55425c602', 'Seated Side Bend Elbow To Floor Tap', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. You''ll also feel your abs working to support the movement. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '69691201', '69691201-Sitting-Side-Bend-Elbow-to-Floor-Tap-(female)_Wais.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself on the floor for Seated Side Bend Elbow To Floor Tap. 2. Sit on the floor with your legs positioned as required. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'side_bend', 'Seated Side Bend Elbow To Floor Tap', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('58a1b6ca-30eb-42ce-a786-c0772d18d551', 'Hang Clean (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. Your quads, glutes, traps work as secondary movers, adding to the training stimulus. The kettlebell grip position adds a unique training stimulus. Compound movements like this develop coordination, power, and overall fitness.', '5351201', '05351201-Kettlebell-Hang-Clean_thighs.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Select an appropriately weighted kettlebell for Kettlebell Hang Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'clean', 'Hang Clean', 'power_clean, clean, front_squat', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('58a2f30c-67d2-452a-9fdc-b645c8d4943a', 'Bulgarian Squat (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '72071201', '72071201-Resistance-Band-Bulgarian-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Bulgarian Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'split_squat', 'Bulgarian Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('58a4b5f7-b751-4ddc-b2ee-9a667d20ab51', 'Pause Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '53001201', '53001201-Dumbbell-Pause-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Pause Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Pause for 1-3 seconds at the bottom or peak of the movement before continuing. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Pause Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('58abbf77-5a1b-47a8-ab7a-4298f37cbdb7', 'Seated Bent Over Reverse Fly (Resistance Band, Chair)', 'Shoulders', 'Resistance Band, Chair, Anchor Point', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build balanced shoulders by working the posterior delts with this flying exercise. You''ll also feel your upper back working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '91461201', '91461201-Resistance-Band-Sitting-Bent-Over-Reverse-Fly-on-a.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Seated Bent Over Reverse Fly On A Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. With a slight bend in your elbows, move the weight in a wide arc. 5. Squeeze your chest muscles at the center/top of the movement. 6. Return with control, feeling the stretch at the bottom. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'rear_delt', 'Seated Bent Over Reverse Fly On A Chair', 'bench_press, incline_bench_press, push_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('58c2b5bb-9eac-463b-ac2b-4d021ee8216c', 'Back Shrug (Smith Machine)', 'Back', 'Smith Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function. Works well as both a primary exercise or accessory movement.', '7461201', '07461201-Smith-Back-Shrug_Back.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Back Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Smith Back Shrug', 'Back Shrug', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('58c8f57e-6756-4031-8a4b-939e1215b788', 'Kneeling Leg Curl (Machine)', 'Legs', 'Machine', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This curling movement works your hamstrings for balanced leg development. You''ll also feel your calves working to support the movement. The kneeling position adds a core stability challenge. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '36091201', '36091201-Lever-Kneeling-Leg-Curl-(plate-loaded)-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Kneeling Leg Curl. 2. Kneel on the floor (use a pad for comfort if needed). 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'leg_curl', 'Lever Kneeling Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('58e26321-51f8-44bc-a563-f9319bec2bdc', 'Landmine Half Kneeling Shoulders Press (Landmine)', 'Core', 'Landmine Attachment, Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Landmine Half Kneeling Shoulders Press is a flexibility exercise that targets your core, helping to release tension and improve range of motion. Kneeling helps eliminate lower body momentum from the movement. Include this in your routine for better mobility and reduced muscle tension.', '107671201', '107671201-Landmine-Half-Kneeling-Shoulders-Press-(female)_S.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Landmine Half Kneeling Shoulders Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('58e9f346-b1c5-4e0c-aba5-993a8f5eebfa', 'Front Plank (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Suspender Front Plank is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '11141201', '11141201-Suspender-Front-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Front Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'plank', 'Suspender Front Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('58fda365-9a49-404e-a8d4-8bc43578b72c', 'Standing Pelvic Tilt', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Pelvic Tilt is a movement exercise that develops back strength and muscle. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '13641201', '13641201-Standing-Pelvic-Tilt_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Pelvic Tilt. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Pelvic Tilt', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5916a833-adf4-447f-8c2a-154ca50496f2', 'Incline Bicep Curl (Cable)', 'Arms', 'Cables, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '57031201', '57031201-Cable-Incline-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 93, 5, 7, FALSE, TRUE, 'bicep_curl', 'Incline Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5920d43b-4087-494a-8d80-7656635be2ca', 'Wind Side Twist Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this twisting exercise that develops speed, power, and coordination. Your abs work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '57931201', '57931201-Wind-Side-Twist-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Rotate your torso through the movement pattern for Wind Side Twist Jump. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'russian_twist', 'Wind Side Twist Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5926bc7a-a30c-43cd-b074-db724617fb9a', 'Standing French Press (EZ Bar)', 'Arms', 'EZ Bar', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'The EZ Bar Standing French Press is an arm pressing exercise targeting your full body. The standing position engages your core for stability. Dedicated arm training builds both strength and muscular definition.', '97341201', '97341201-EZ-Bar-Standing-French-Press-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Begin in a standing position with good posture. 3. Execute the pressing motion for EZ Bar Standing French Press, extending through the target muscles. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'tricep_extension', 'EZ Bar Standing French Press', 'tricep_pushdown, close_grip_bench', TRUE, 'ez_bar', FALSE, 3, 90, 4, 95, 80, 65, 95),
('593473b6-4a19-4442-99f1-eaed3e2e7910', 'Standing Hip Extension (Cable)', 'Legs', 'Cables', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Cable Standing Hip Extension is a hip-dominant extension exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Cable resistance creates smooth, continuous muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '2281201', '02281201-Cable-Standing-Hip-Extension_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Hip Extension. 2. Stand with feet about shoulder-width apart. 3. Extend through the target joint(s) for Cable Standing Hip Extension. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Hip Extension', 'hip_thrust, lunge, squat', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5938e121-177b-4d3a-9d29-f6a4001f0230', 'Step Out From Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Step Out From Squat is a squatting exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '83741201', '83741201-Step-Out-from-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'step_up', 'Step Out From Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5948a254-d249-4ff7-9765-9a3f60cea83f', 'Seated Stepout Hands Up (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target your full body with the Seated Stepout Hands Up On A Chair, an effective shoulder stepping exercise. Secondary activation of your quads provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Shoulder development enhances both performance and upper body aesthetics.', '81981201', '81981201-Sitting-StepOut-Hands-Up-on-a-Chair-(male)_Shoulde.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up a box or step platform at the appropriate height. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Stepout Hands Up On A Chair', 'crunch, leg_raise, plank', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5954cbbf-b98e-4810-9562-6891b06d5f3f', 'Front Raise (Band)', 'Shoulders', 'Resistance Band', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This raising exercise works your front delts for improved shoulder strength and aesthetics. Bands are joint-friendly and portable, perfect for any training environment. Strong shoulders improve overhead strength and support nearly all upper body movements.', '9781201', '09781201-Band-front-raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Secure the resistance band appropriately for Band Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('59591d3d-a461-46cf-8a3d-26bdf34125fa', 'Front Raise - Reverse Grip (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Cable Reverse Grip Front Raise is a raising exercise that targets your front delts for shoulder development. Cable resistance creates smooth, continuous muscle engagement. Shoulder development enhances both performance and upper body aesthetics.', '106351201', '106351201-Cable-Reverse-Grip-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Adjust the cable machine to the correct height and attachment for Cable Reverse Grip Front Raise. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise - Reverse Grip', 'Front Raise - Reverse Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('595c0c54-e3dc-41bb-864b-262b431728be', 'Seated Windshield Wipers (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Windshield Wipers On A Chair is a core movement exercise that primarily targets your abs. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '83071201', '83071201-Seated-Windshield-Wipers-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Windshield Wipers On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('595c5785-97b3-47e3-a877-db346f834c61', 'High Knee Sprints', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'Enhance your stamina and burn calories with this effective cardio movement. You''ll also feel your hip flexors working to support the movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight. Can be modified for beginners or progressed for advanced athletes.', '71661201', '71661201-High-Knee-Sprints-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for High Knee Sprints. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Sprints', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('595f56c4-0a1c-4275-a35b-a0c2a2450406', 'Seated Lean Back Open And Close (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Lean Back Open And Close On A Chair, focusing on your core. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '83011201', '83011201-Seated-Lean-Back-Open-and-Close-on-a-Chair-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Lean Back Open And Close On A Chair', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('59617e9c-9943-47a5-93ba-d4dcf6a57f35', 'Suspended Abdominal Fallout', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Suspended Abdominal Fallout, focusing on your abs. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '8051201', '08051201-Suspended-Abdominal-Fallout_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Set up in the starting position for Suspended Abdominal Fallout. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspended Abdominal Fallout', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5973ddf2-05fb-4989-8217-fccaad05a853', 'Hip Bridge (TRX)', 'Legs', 'TRX', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. Strong legs are the foundation for athletic performance and functional fitness.', '10781201', '10781201-Suspender-Hip-Bridge-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Hip Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'glute_bridge', 'Suspender Hip Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5978eb98-8178-44df-89f0-490c6a2b04a7', 'Ring Plank (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Ring Plank is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A strong core improves posture, protects your spine, and enhances all other lifts.', '78761201', '78761201-Ring-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'plank', 'Ring Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'gymnastic_rings', TRUE, 3, 90, 4, 68, 85, 85, 70),
('597b3f12-ed9d-4cf7-b413-caa4cd6b03ff', 'Push Jerk (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint pushing movement. The dumbbell variation provides freedom of movement and greater range of motion. Compound movements like this develop coordination, power, and overall fitness.', '43891201', '43891201-Dumbbell-Push-Jerk_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Push Jerk. 2. Set up in the starting position for Dumbbell Push Jerk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'jerk', 'Push Jerk', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('5986eb8b-8f7d-4e68-ade4-2c58231353ad', 'Seated Side Glute Lift (Chair)', 'Legs', 'Chair', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this movement movement focused on hip extension. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '82821201', '82821201-Seated-Side-Glute-Lift-on-a-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep your core engaged for stability. Perfect for targeting your glutes.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'glute_exercise', 'Seated Side Glute Lift On A Chair', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('59882198-adfa-4a05-a137-1e64d14585d1', 'Rope Pull Side Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic pulling movement gets your heart rate up while developing explosive strength. The quads assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '56811201', '56811201-Rope-Pull-Side-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Rope Pull Side Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Rope Pull Side Step', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('598aed2e-8cef-40ce-81df-3a3debb801e2', 'Kneeling To Standing Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Kneeling To Standing Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '85331201', '85331201-Kneeling-to-Standing-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Stand with feet about shoulder-width apart. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'squat', 'Kneeling To Standing Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5990006d-2b0f-4478-bcfa-56788b74b26a', 'Cross Abduction (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '72861201', '72861201-Band-Cross-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Cross Abduction. 2. Set up in the starting position for Band Cross Abduction. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Cross Abduction', 'plank, crunch, leg_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('599b785a-08cc-4c2b-a2a6-08da76aebc3f', 'Plank Walk Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this squatting exercise that develops speed, power, and coordination. Secondary activation of your shoulders, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '71531201', '71531201-Plank-Walk-Squat-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. An effective movement for your plyometrics routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Plank Walk Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('59a77986-40b5-4cc4-919d-9b6bd623d452', 'Run And Jack Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your quads, calves provides additional muscle engagement. Regular cardio training builds the aerobic base for better overall fitness.', '32701201', '32701201-Run-and-Jack-Jump-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up in the starting position for Run And Jack Jump. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'running', 'Run And Jack Jump', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('59b09a1e-6f3b-4db2-a7bb-cce21a56fc50', 'Seated Knee Extension (Stability Ball)', 'Legs', 'Stability Ball', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this extension exercise for quad development. Being seated provides stability, allowing you to focus on the working muscles. Using a ball requires constant core engagement to maintain balance. Strong legs are the foundation for athletic performance and functional fitness.', '92761201', '92761201-Sitting-Knee-Extension-on-a-Stability-Ball-(female.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position the stability ball as needed for Seated Knee Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend through the target joint(s) for Seated Knee Extension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Knee Extension', 'squat, leg_press, lunge', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('59be9976-a611-431f-b77f-002ba154ac2b', 'Half Kneeling Halo (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Kettlebell Half Kneeling Halo, an effective shoulder movement exercise. The kneeling position adds a core stability challenge. The kettlebell grip position adds a unique training stimulus. Strong shoulders improve overhead strength and support nearly all upper body movements.', '83311201', '83311201-Kettlebell-Half-Kneeling-Halo-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Select an appropriately weighted kettlebell for Kettlebell Half Kneeling Halo. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Half Kneeling Halo', 'squat, leg_extension, lunge', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('59becec4-3fe0-4c3f-b9be-e429adecf5f4', 'Side Step Front Punches', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Side Step Front Punches builds reactive power and improves conditioning. You''ll also feel your shoulders working to support the movement. Great for improving athletic performance, burning calories, and building conditioning.', '79511201', '79511201-Side-Step-Front-Punches-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Front Punches. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Front Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('59d85080-8113-4413-b918-ef7678efe578', 'Jefferson Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Bodyweight Jefferson Curl is a lower body curling exercise that targets your biceps. The forearms assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '107521201', '107521201-Bodyweight-Jefferson-Curl-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. Perfect for targeting your biceps.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'bicep_curl', 'Jefferson Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('59e85a65-8f63-455d-a836-5472e04f9fa5', 'Balance Board', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Balance Board is a lower body movement exercise that targets your core. The legs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '66941201', '66941201-Balance-Board-(female)-(VERSION-2)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Balance Board. 2. Execute the movement with proper form, focusing on your core. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'balance', 'Balance Board', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('59f36ba9-a99e-4dcd-a245-3ee798b15f30', 'Seated Forward Reach', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Forward Reach provides a deep stretch for your hamstrings, ideal for recovery and mobility work. Secondary activation of your lower back provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '82111201', '82111201-Seated-Forward-Reach-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Forward Reach. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'hamstring_stretch', 'Seated Forward Reach', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('59f45941-2627-4407-afd0-08cfcd74ccc9', 'V Up (Dumbbell) - Alternating', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Dumbbell Alternate V Up is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Building core stability helps with everything from heavy deadlifts to daily activities.', '68051201', '68051201-Dumbbell-Alternate-V-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternate V Up. 2. Alternate between sides/arms/legs with each repetition. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'v_up', 'V Up - Alternating', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('59f84bf6-1d28-4284-98ab-c429bcf058ad', 'Seated Quads Stretch (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Secondary activation of your hip flexors provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '91731201', '91731201-Sitting-Quads-Stretch-on-a-Chair-(female)_Stretchi.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Quads Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Quads Stretch On A Chair', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5a031445-0242-48be-95bd-b9a694756097', 'Standing Crunch - Rope (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Standing Crunch (with Rope Attachment), focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '8741201', '08741201-Cable-Standing-Crunch-(with-rope-attachment)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Crunch. 2. Stand tall with your feet firmly planted. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'crunch', 'Standing Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5a11b195-1112-476f-9825-0295c1423389', 'Standing Abs Rotation Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this rotation exercise that strengthens your obliques. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '42681201', '42681201-Standing-Abs-Rotation-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Abs Rotation Stretch. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Abs Rotation Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5a169887-5c97-486d-ba24-0bb0cb5c5043', 'Kneeling Leg Out Twist Reach', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Your abs work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. Flexibility work like this enhances performance and prevents stiffness.', '82151201', '82151201-Kneeling-Leg-Out-Twist-Reach-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Rotate your torso through the movement pattern for Kneeling Leg Out Twist Reach. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Kneeling Leg Out Twist Reach', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5a297117-f23b-4df1-811d-ac534a230f3b', 'Leg Reach Crunch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '73971201', '73971201-Alternate-Leg-Reach-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Leg Reach Crunch - Alternating', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5a2e2cbe-f576-4fa8-afe6-7416abf1af41', 'Coner Wall Chest Stretch (Wall)', 'Chest', 'Wall, Cones', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This stretching exercise focuses on your pectorals for improved chest strength and development. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '89961201', '89961201-Coner-Wall-Chest-Stretch-(VERSION-2)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Coner Wall Chest Stretch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 32, 2, 6, FALSE, TRUE, 'chest_stretch', 'Coner Wall Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5a317145-4247-4fd1-9d39-3abd26557290', 'Shoulder Press (Machine)', 'Shoulders', 'Machine', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. You''ll also feel your triceps working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Machine exercises are great for isolating muscles and training to failure safely. Shoulder development enhances both performance and upper body aesthetics.', '28831201', '28831201-Lever-Seated-Shoulder-Press-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Shoulder Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'shoulder_press', 'Lever Seated Shoulder Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('5a363749-8f8e-4c50-bd6a-bfddbdfa70f1', 'Ring Dip (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Ring Dip targets your triceps through a dipping motion. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Arm strength supports grip, pulling, and pushing in compound movements.', '6771201', '06771201-Ring-Dip_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'dip', 'Ring Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5a39bc92-25c0-4ffc-9ffc-bd25e1f5942c', 'Standing Crush Curl (Kettlebell)', 'Arms', 'Kettlebell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. The standing position engages your core for stability. The kettlebell grip position adds a unique training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '64871201', '64871201-Kettlebell-Standing-Crush-Curl-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing Crush Curl. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Crush Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('5a625fe0-eb72-4b37-8bf9-495d533208ae', 'Leaning Forward Side Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength. Maintain proper breathing - exhale during the effort phase.', '96621201', '96621201-Leaning-Forward-Side-Lunge-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Leaning Forward Side Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5a63d7b4-0241-494e-a39a-65f5141b4f6b', 'Seated Press (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Being seated provides stability, allowing you to focus on the working muscles. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '3881201', '03881201-Dumbbell-Seated-Alternate-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Alternate Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Alternate between sides/arms/legs with each repetition. 7. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Press - Alternating', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('5a6bf74d-2606-4e9d-88c9-995a77f5b692', 'Chest Dip (TRX)', 'Chest', 'TRX', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this dipping movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Suspension training adds instability, increasing core activation throughout. A well-developed chest contributes to upper body strength and aesthetics.', '10721201', '10721201-Suspender-Chest-Dip-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Chest Dip. 2. Lower your body by bending your elbows to about 90 degrees. 3. Push back up until your arms are fully extended. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'dip', 'Suspender Chest Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5a6d56ef-533e-4e0e-afec-25f2a86a5505', 'Incline Elbow Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Incline Elbow Plank, focusing on your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. Core strength is foundational for athletic performance and injury prevention.', '76891201', '76891201-Incline-Elbow-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'plank', 'Incline Elbow Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5a6f4794-280a-42b1-99bb-0e5bd50d27c3', 'Chest Fly Side Step', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '55881201', '55881201-Chest-Fly-Side-Step-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly Side Step', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5a79572c-a433-4f62-acba-66fefca4bc09', 'Side Lying Chest Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Side Lying Chest Stretch, an effective stretching movement for upper body strength. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '82891201', '82891201-Side-Lying-Chest-Stretch-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Chest Stretch. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'chest_stretch', 'Side Lying Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5a7a98a8-c97c-4fcd-ac60-29ebcdfc5fa9', 'High Knee Tap', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '55371201', '55371201-High-Knee-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Set up in the starting position for High Knee Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Tap', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5a7c2179-a5b6-47b5-baf2-643ad7b444fd', 'Pull Up (TRX)', 'Back', 'TRX', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '11271201', '11271201-Suspender-Pull-up-(version-2)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Pull Up. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'pull_up', 'Suspender Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5a82cd97-31ff-4a6c-b495-503b9571a37f', 'Reverse Crunch Leg Drop', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention. Perfect for including in both strength and hypertrophy programs.', '73901201', '73901201-Reverse-Crunch-Leg-Drop-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch Leg Drop', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5a873103-8b62-4b10-af15-dcdfaa57204e', 'Side Lunge (Wall Supported) - Alternating', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Alternate Side Lunge Wall Supported is a lunging exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '99071201', '99071201-Alternate-Side-Lunge-Wall-Supported-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Position yourself at the appropriate distance from a wall. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge Wall Supported - Alternating', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5a8a790e-0cd3-4575-8ab4-1a745da693e6', 'Palm Push March', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic pushing movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '84011201', '84011201-Palm-Push-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Palm Push March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Palm Push March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5aa938e5-c9d8-4c71-a60a-e9280515b54e', 'Lying Arms Slide', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '82281201', '82281201-Lying-Arms-Slide-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Arms Slide. 2. Set up in the starting position for Lying Arms Slide. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Lying Arms Slide', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5aac5d4c-9f8f-4089-9bc4-82565653a4c9', 'Back Pec Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This stretch specifically works on your back, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Maintain proper breathing - exhale during the effort phase.', '45151201', '45151201-Back-Pec-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Move into the stretch position for Back Pec Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'chest_stretch', 'Back Pec Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5aae7a73-bb54-45a7-b992-9534d4e43725', 'Front Plank With Leg Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build leg strength with this stabilization movement focusing on your abs. You''ll also feel your shoulders, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '28981201', '28981201-Front-Plank-with-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Front Plank With Leg Lift', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5ab9260b-cef1-4304-847d-e63d4be81de3', 'Olympic (Barbell) Hammer Curl', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Olympic Barbell Hammer Curl is a curling exercise that isolates your biceps. You''ll also feel your forearms working to support the movement. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements.', '6361201', '06361201-Olympic-Barbell-Hammer-Curl_Forearms.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Grip a barbell with hands at the appropriate width for Olympic Barbell Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'hammer_curl', 'Olympic Hammer Curl', 'Olympic Hammer Curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('5abe42ef-7201-4405-8bd2-1c906f30cef1', 'Crunch (arms On Chest)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '47271201', '47271201-Crunch-(arms-on-chest)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5aca8dc6-6ea9-4cc8-b06e-2e24e38916e6', 'Double Punch Front Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'The Double Punch Front Leg Lift is an explosive exercise that combines cardiovascular training with dynamic movement movements. Secondary activation of your shoulders provides additional muscle engagement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '58331201', '58331201-Double-Punch-Front-Leg-Lift-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Double Punch Front Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Double Punch Front Leg Lift', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5acd998f-ea8e-4aef-b8e8-9376d43177cf', 'Wood Chop (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. Your shoulders work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Core strength is foundational for athletic performance and injury prevention.', '80491201', '80491201-Dumbbell-Wood-Chop-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Wood Chop. 2. Set up in the starting position for Dumbbell Wood Chop. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 62, 9, 8, TRUE, TRUE, 'woodchop', 'Wood Chop', 'russian_twist, pallof_press, cable_crunch', FALSE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('5af5dec1-bb00-4d47-8db7-013f833942ae', 'Assisted Shoulder Abduction Walk (TRX)', 'Legs', 'TRX', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. The TRX allows you to adjust difficulty by changing your body angle. Plyometric training builds explosive power that transfers to sports and daily activities.', '101621201', '101621201-Suspender-Assisted-Shoulder-Abduction-Walk-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Assisted Shoulder Abduction Walk. 2. Set up in the starting position for Suspender Assisted Shoulder Abduction Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'hip_abduction', 'Suspender Assisted Shoulder Abduction Walk', 'lateral_raise, shoulder_press, front_raise', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5af9a68a-55c7-40d4-8c4d-7b338c5f19b5', 'Potty Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '31181201', '31181201-Potty-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Ensure full range of motion on each rep. This exercise is excellent for quads development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Potty Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b01720b-f3f7-4a67-93b8-5d7da4068e7f', 'Wind Side Twist Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity twisting exercise that challenges your entire body. The abs assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '67801201', '67801201-Wind-Side-Twist-Jump-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Rotate your torso through the movement pattern for Wind Side Twist Jump. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'russian_twist', 'Wind Side Twist Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5b0badcd-8e87-4249-b554-1595bd130630', 'Lying Single Knee Swing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Single Knee Swing provides a deep stretch for your full body, ideal for recovery and mobility work. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '82071201', '82071201-Lying-Single-Knee-Swing-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Knee Swing. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Single Knee Swing', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b0bf92c-8ee2-402e-b488-3614f3895589', 'Standing Triangle Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '48741201', '48741201-Bodyweight-Standing-Triangle-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Stand with feet about shoulder-width apart. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'yoga', 'Standing Triangle Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5b0cdf5c-e545-4d58-95de-881939396002', 'Bicep Curl - Front Step', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'A challenging plyometric exercise, the Biceps Curl Front Step builds reactive power and improves conditioning. Secondary activation of your forearms provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '56441201', '56441201-Biceps-Curl-Front Step-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Set up a box or step platform at the appropriate height. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl Front Step', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5b38f4a9-e49a-4fb7-a1e6-6e8f3841d1d4', 'Seated Calf Stretch (Towel)', 'Legs', 'Towel', '{"Calves"}'::text[], '{}'::text[], 'The Seated Calf Stretch With Towel is a flexibility exercise that targets your calves, helping to release tension and improve range of motion. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '94571201', '94571201-Sitting-Calf-Stretch-with-Towel-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Calf Stretch With Towel. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'calf_stretch', 'Seated Calf Stretch With Towel', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5b49df03-1094-4344-b7a8-18e81591f3c8', 'Single Leg Deadlift (Dumbbell)', 'Back', 'Dumbbells', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '26351201', '26351201-Dumbbell-Single-Leg-Deadlift-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'deadlift', 'Single Leg Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('5b4a836e-814d-4195-ada5-74b9b73a2ada', 'Reverse Hyper On Flat Bench', 'Legs', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Reverse Hyper On Flat Bench is a lower body movement exercise that targets your lower back. You''ll also feel your glutes working to support the movement. Leg training boosts metabolism and builds functional, real-world strength.', '57331201', '57331201-Reverse-Hyper-on-Flat-Bench-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Use a flat bench for this exercise. 2. Set up in the starting position for Reverse Hyper On Flat Bench. 3. Execute the movement with proper form, focusing on your lower back. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Reverse Hyper On Flat Bench', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b4bee64-7a0b-47ea-9b77-5377f64f5098', 'Vertical Squat (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '55201201', '55201201-Lever-Vertical-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Vertical Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Lever Vertical Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('5b4d38f0-b71d-465c-a190-0ff871b67614', 'Roll Erector Spinae Lying On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '54261201', '54261201-Roll-Erector-Spinae-Lying-on-Floor-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Erector Spinae Lying On Floor. 2. Lie down in the appropriate position for Roll Erector Spinae Lying On Floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'cycling', 'Roll Erector Spinae Lying On Floor', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b4e92d0-615e-4ff7-8ba7-98ca7172fc05', 'Mountain Climber Over Bench', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'This climbing exercise engages your abs for improved core stability and strength. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. Core strength is foundational for athletic performance and injury prevention.', '78081201', '78081201-Mountain-Climber-over-Bench_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Over Bench', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5b5824d3-1ccc-45a6-9dce-e183d0aa0cd0', 'Roll Plank (Medicine Ball)', 'Core', 'Medicine Ball', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Medicine Ball Roll Plank is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Building core stability helps with everything from heavy deadlifts to daily activities.', '76111201', '76111201-Medicine-Ball-Roll-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Roll Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Medicine Ball Roll Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'medicine_ball', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5b67f6cc-88a7-4f41-a6fe-5ff940a8b68e', 'Pull In (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This pulling exercise engages your abs for improved core stability and strength. The stability ball adds an instability challenge that activates more stabilizer muscles. Core strength is foundational for athletic performance and injury prevention.', '60301201', '60301201-Pull-In-(on-stability-ball)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Position the stability ball as needed for Pull In. 2. Set up in the starting position for Pull In. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Pull In', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b6b4c8b-20d3-4961-835f-d0e98771c019', 'Forward Backward Quick Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Forward Backward Quick Step builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '81331201', '81331201-Forward-Backward-Quick-Step-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Forward Backward Quick Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Forward Backward Quick Step', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5b6fe7f9-1bee-40e5-8f4b-6764ec101aea', 'Wide Stance Jump Squat To Narrow Stance Jump Squat', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger quads with this rowing movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '58651201', '58651201-Wide-Stance-Jump-Squat-to-Narrow-Stance-Jump-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat_jump', 'Wide Stance Jump Squat To Narrow Stance Jump Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5b8b96f3-6f44-465c-bbdb-b32405e48d08', 'Standing Single Front Leg Raise (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. Performing this standing challenges your balance and core engagement. Core strength is foundational for athletic performance and injury prevention.', '86351201', '86351201-Standing-Single-Front-Leg-Raise-Chair-Supported-(f.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Stand tall with your feet firmly planted. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Single Front Leg Raise Chair Supported', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5b90f173-47d5-4e3b-a6e9-aea4651451e1', 'Side Bent (Barbell)', 'Core', 'Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Using a barbell provides stability for progressive overload. Building core stability helps with everything from heavy deadlifts to daily activities.', '961201', '00961201-Barbell-Side-Bent-(version-2)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Grip a barbell with hands at the appropriate width for Barbell Side Bent. 2. Set up in the starting position for Barbell Side Bent. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Bent', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('5ba6da72-c5ae-45fa-b0ac-7a0516f38e0e', 'Reverse Lunge High Knee Forward Lunge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '74121201', '74121201-Reverse-Lunge-High-Knee-Forward-Lunge-(male)_Thigh.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge High Knee Forward Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5bb2e9e9-af67-4675-b670-a0c6eb41e47e', 'Single Arm Triceps Extension (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell One Arm Triceps Extension targets your triceps through a extension motion. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '43431201', '43431201-Dumbbell-One-Arm-Triceps-Extension-(female)_Upper-.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'tricep_extension', 'Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5bb986de-b395-4028-9b08-24c5a371883d', 'Squat Step Out (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '72031201', '72031201-Resistance-Band-Squat-Step-Out-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Squat Step Out. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'step_up', 'Squat Step Out', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('5bcb62fc-26b4-46f2-8ed6-1fbe8fde8727', 'Step Up (Barbell)', 'Legs', 'Barbell, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts.', '25011201', '25011201-Barbell-Step-up-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'step_up', 'Step Up', 'lunge, split_squat, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('5bd0665e-1c68-4260-80ce-3fcfd8abf41e', 'Lying Leg Raise - Waist (Resistance Band)', 'Core', 'Resistance Band', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Lying Leg Raise (waist) is a core raising exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Bands are joint-friendly and portable, perfect for any training environment. Core strength is foundational for athletic performance and injury prevention.', '72011201', '72011201-Resistance-Band-Lying-Leg-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lying Leg Raise. 2. Lie down in the appropriate position for Resistance Band Lying Leg Raise. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'leg_raise', 'Lying Leg Raise', 'crunch, plank, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('5bd3444f-cb1f-4b3a-9662-67dac575ba2c', 'Chest Fly Shoulders', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Secondary activation of your front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '104741201', '104741201-Chest-Fly---Shoulders-(WRONG-RIGHT)_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Chest Fly Shoulders', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5bdc4e78-543c-4da5-a9d0-943adc3c6ae1', 'Seated Lateral Raise (Band)', 'Shoulders', 'Resistance Band', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Being seated provides stability, allowing you to focus on the working muscles. The band creates increasing tension as it stretches, challenging the lockout. Strong shoulders improve overhead strength and support nearly all upper body movements.', '68441201', '68441201-Band-Seated-Lateral-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Secure the resistance band appropriately for Band Seated Lateral Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'lateral_raise', 'Seated Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('5be7754c-afb0-4f5d-b4e3-9cbe49cc1010', 'Standing Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '22341201', '22341201-Dumbbell-Standing-Lateral-Raise-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Lateral Raise. 2. Stand with feet about shoulder-width apart. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5beda0ae-d254-41e5-8802-5c9d130f05ee', 'Single Arm Triceps Pushdown (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pushing exercise for bigger arms. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '74251201', '74251201-Cable-One-Arm-Tricep-Pushdown-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Triceps Pushdown. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Single Arm Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', TRUE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5bef2b98-5556-4754-8018-a2e75d2034da', 'Seated Row - Underhand Grip (Plate Loaded Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '79351201', '79351201-Lever-Supinated-Grip-Seated-Row-(plate-loaded)_Bac.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Supinated Grip Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use an underhand (supinated) grip with palms facing up/toward you. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Supinated Grip Seated Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('5bf9ead1-460a-403d-8ed0-14126d848393', 'Landmine Shoulder To Shoulder Press (Landmine)', 'Shoulders', 'Landmine Attachment, Barbell', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your triceps provides additional muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '65951201', '65951201-Landmine-Shoulder-To-Shoulder-Press-(male)_Shoulde.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Start with the weight at shoulder level. 2. Press directly overhead until your arms are fully extended. 3. Lower back to shoulder level with control. 4. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'shoulder_press', 'Landmine Shoulder To Shoulder Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('5c091c8d-0b86-415a-a683-15bca68fe0c0', 'Kneeling Twist (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Cable Kneeling Twist targets your obliques through a twisting motion, building rotational core strength. The abs assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. The cable setup allows you to adjust the angle of resistance. Core strength is foundational for athletic performance and injury prevention.', '67601201', '67601201-Cable-Kneeling-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Twist. 2. Kneel on the floor (use a pad for comfort if needed). 3. Rotate your torso through the movement pattern for Cable Kneeling Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'russian_twist', 'Kneeling Twist', 'squat, leg_extension, lunge', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('5c0e5ea6-f49b-4bf8-9085-24a617d99726', 'Landmine Single Leg Romanian Deadlift (Landmine)', 'Legs', 'Landmine Attachment, Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. Strong legs are the foundation for athletic performance and functional fitness. Focus on controlled form throughout each repetition.', '65531201', '65531201-Landmine-Single-Leg-Romanian-Deadlift-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Push your hips back, lowering the weight along your legs with a flat back. 2. Lower until you feel a stretch in your hamstrings. 3. Drive hips forward to stand, squeezing glutes at the top. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Landmine Single Leg Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('5c1c8170-a937-4370-9a4c-bef261289cbb', 'Double Woodchoppers', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Double Woodchoppers is an explosive exercise that combines cardiovascular training with dynamic movement movements. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '75691201', '75691201-Double-Woodchoppers-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Set up in the starting position for Double Woodchoppers. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'woodchop', 'Double Woodchoppers', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5c22cc95-cf7b-4d85-89d3-0670403ca392', 'Step Knee Thrust', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic thrusting movement gets your heart rate up while developing explosive strength. Your quads work as secondary movers, adding to the training stimulus. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '57941201', '57941201-Step-Knee-Thrust-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up a box or step platform at the appropriate height. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Step Knee Thrust', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5c2b8624-6938-4285-9795-6d8422b4c9d3', 'Lying Oblique V Up (Dumbbell)', 'Core', 'Dumbbells, Flat Bench', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Dumbbell Lying Oblique V Up, focusing on your abs. You''ll also feel your abs working to support the movement. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '67991201', '67991201-Dumbbell-Lying-Oblique-V-Up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Oblique V Up. 2. Lie down in the appropriate position for Dumbbell Lying Oblique V Up. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'v_up', 'Lying Oblique V Up', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('5c303e2b-7648-4743-93ba-f09072a8df19', 'Side Step Chest Squeeze', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Chest Squeeze is an explosive exercise that combines cardiovascular training with dynamic stepping movements. You''ll also feel your quads working to support the movement. Great for improving athletic performance, burning calories, and building conditioning.', '76601201', '76601201-Side-Step-Chest-Squeez-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Chest Squeeze. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_exercise', 'Side Step Chest Squeeze', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5c30c64a-fbed-4f66-a914-6bfe6f3d9532', 'Incline Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '70721201', '70721201-Dumbbell-Incline-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'front_raise', 'Incline Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5c337d29-9ac1-43ae-9a96-85418a70b989', 'Deep Breathe Flaps Plyo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Aim for full range of motion on every rep.', '90501201', '90501201-Deep-Breathe-Flaps-Plyo-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set. A solid choice for legs day.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'breathing', 'Deep Breathe Flaps Plyo Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5c3b04e9-b770-426b-a010-a1afa60894b5', 'Single Arm Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. You''ll also feel your hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '3541201', '03541201-Dumbbell-One-Arm-Kickback_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Single Arm Kickback', 'bicep_curl, tricep_extension, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5c3b94d0-6023-4513-b698-22161610364b', 'High Row - Kneeling Rope Attachment (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable High Row (kneeling Rope Attachment) is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. The kneeling position adds a core stability challenge. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '1671201', '01671201-Cable-High-Row-(kneeling-rope-attachment)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'cable_row', 'High Row', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('5c601f3a-26d1-4737-9d5c-da7e56a1ed06', 'Airbike (Air Bike)', 'Core', 'Air Bike', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Air Bike is a core movement exercise that primarily targets your abs. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '31201', '00031201-Air-Bike-(male)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Set up in the starting position for Air Bike. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, 'Push/Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 2, 2, NULL, 10, 'Lying', NULL, 'Neutral', 'Standard', 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'cycling', 'Airbike', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('5c6179d3-4372-41ca-af80-ae176d638cec', 'Shoulder Press - Single Arm (Plate Loaded Machine)', 'Shoulders', 'Machine', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Lever Single Arm Shoulder Press (plate Loaded) (VE, an effective shoulder pressing exercise. The triceps assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Strong shoulders improve overhead strength and support nearly all upper body movements.', '88051201', '88051201-Lever-Single-Arm-Shoulder-Press-(plate-loaded)-(VE.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Single Arm Shoulder Press(VE. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'shoulder_press', 'Lever Single Arm Shoulder Press  (VE', 'Lever Single Arm Shoulder Press (VE', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('5c6559da-c137-476f-814f-8cd77fa04529', 'Lying Squat (Sled)', 'Legs', 'Sled', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Leg training boosts metabolism and builds functional, real-world strength.', '7441201', '07441201-Sled-Lying-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Lie down in the appropriate position for Sled Lying Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Sled Lying Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5c67af2f-90c1-40e9-bbcf-bc1aa2011616', 'Inverted Row (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your biceps provides additional muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '35201201', '35201201-Inverted-Row-between-Chairs-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Inverted Row Between Chairs', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5c6d9a19-6090-4175-9372-1e23c9e66312', 'Star Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '72461201', '72461201-Star-Plank-(male)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Star Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5c806409-3254-4d1c-abc7-7ba4c3c8c3f1', 'Ring Elevated Pike Push Up From Deficit (Gymnastic Rings)', 'Chest', 'Gymnastic Rings, Step Platform', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build stronger shoulders with this pushing movement focusing on your chest. Your triceps, front delts work as secondary movers, adding to the training stimulus. Strong shoulders improve overhead strength and support nearly all upper body movements.', '93161201', '93161201-Ring-Elevanted-Pike-Push-up-from-deficit-(male)_Sh.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'push_up', 'Ring Elevanted Pike Push Up From Deficit', 'bench_press, chest_fly, dip', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5c840164-b490-4c9e-865b-a52c2178ba02', 'Triceps Kickback (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'The Band Triceps Kickback targets your triceps through a kicking motion. The hamstrings assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '41431201', '41431201-Band-Triceps-Kickback_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Secure the resistance band appropriately for Band Triceps Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('5c855965-3a5d-4c18-b33e-7c5ec46fa34f', 'Intermediate Hip Flexor And Quad Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Intermediate Hip Flexor And Quad Stretch provides a deep stretch for your quads, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '42811201', '42811201-Intermediate-Hip-Flexor-and-Quad-Stretch-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Move into the stretch position for Intermediate Hip Flexor And Quad Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'quad_stretch', 'Intermediate Hip Flexor And Quad Stretch', 'stretch_hip, stretch_hamstring', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5c85f9e9-a1c3-4cca-a411-742aeead036c', 'Battling Ropes High Waves', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '33791201', '33791201-Battling-Ropes-High-Waves_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Set up in the starting position for Battling Ropes High Waves. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Battling Ropes High Waves', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5c8c30e8-a27e-41c4-a828-12718194ae46', 'Seated Rear Lateral Raise (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Cable Seated Rear Lateral Raise is a raising exercise that targets your rear delts for shoulder development. Being seated provides stability, allowing you to focus on the working muscles. Cable resistance creates smooth, continuous muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '2151201', '02151201-Cable-Seated-Rear-Lateral-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Rear Lateral Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Seated Rear Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5c8f3d54-d507-4694-95d4-c53f1527a7b4', 'Bent Over Row (Barbell)', 'Back', 'Barbell', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Barbell Bent Over Row is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. Using a barbell provides stability for progressive overload. A strong back improves posture, prevents injury, and balances pressing movements.', '271201', '00271201-Barbell-Bent-Over-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Grip a barbell with hands at the appropriate width for Barbell Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', 'Row', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing (Hinged)', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('5c92da6d-cac7-4ef3-bf18-d987ba014036', 'Lying Cycle Punches', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Cycle Punches, focusing on your abs. The shoulders assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '81781201', '81781201-Lying-Cycle-Punches-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Lie down in the appropriate position for Lying Cycle Punches. 2. Set up in the starting position for Lying Cycle Punches. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Lying Cycle Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5ca15595-fd35-4b78-ad47-b378e9a7b3c9', 'Standing Shoulder External Rotation (Resistance Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Resistance Band Standing Shoulder External Rotation is a rotation exercise that targets your rotator cuff for shoulder development. The standing position engages your core for stability. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '97581201', '97581201-Resistance-Band-Standing-Shoulder-Extrernal-Rotati.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Shoulder External Rotation. 2. Stand with feet about shoulder-width apart. 3. Rotate your torso through the movement pattern for Resistance Band Standing Shoulder External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'external_rotation', 'Standing Shoulder External Rotation', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('5ca1f94d-a0d5-4cb7-97cb-bd9e2df21142', 'Standing Shoulder Press - Close Grip (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Standing Close Grip Shoulder Press, an effective shoulder pressing exercise. Secondary activation of your triceps provides additional muscle engagement. Performing this standing challenges your balance and core engagement. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '86481201', '86481201-Dumbbell-Standing-Close-Grip-Shoulder-Press-(male).mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Close Grip Shoulder Press. 2. Begin in a standing position with good posture. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Start with the weight at shoulder level. 5. Press directly overhead until your arms are fully extended. 6. Lower back to shoulder level with control. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 94, 7, 8, TRUE, TRUE, 'shoulder_press', 'Standing Shoulder Press - Close Grip', 'Standing Shoulder Press - Close Grip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('5cac83b4-6e2d-43b8-a51b-a39759e7f2e0', 'Seated Lower Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Designed to lengthen your back, the Seated Lower Back Stretch helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '6901201', '06901201-Seated-Lower-Back-Stretch_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Lower Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Lower Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5cb3faae-5fb4-46d3-be10-9065f13be899', 'Lateral Tap In Squat Position', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. Secondary activation of your glutes, hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. A staple exercise that belongs in most training programs.', '56111201', '56111201-Lateral-Tap-in-Squat-Position-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. An effective movement for your plyometrics routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Lateral Tap In Squat Position', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5cb86b67-df5d-4c4c-8fba-a4b70e652976', 'Overhead Tricep Extension (Machine)', 'Arms', 'Machine', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The machine guides your movement path for safer, more controlled repetitions. Arm strength supports grip, pulling, and pushing in compound movements. This variation is excellent for building mind-muscle connection.', '78641201', '78641201-Lever-Overhead-Triceps-Extension-(male)_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Overhead Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lever Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('5cc52fb2-40cd-4d9e-936c-103c7f441fac', 'Seated Back Squeeze Pulse (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Rear Delts"}'::text[], 'This movement exercise strengthens the muscles between your shoulder blades. Your rear delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '91031201', '91031201-Sitting-Back-Squeeze-Pulse-on-a-Chair-(female)_Bac.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. At the bottom or top, pulse up and down in small movements before completing the rep. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'pulse', 'Seated Back Squeeze Pulse On A Chair', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5cc9b24d-c5ba-463d-8494-73482c3ee22d', 'Dynamic 90 90 Hip Twist', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. The glutes assist throughout the movement, making this a well-rounded exercise. Include this in your routine for better mobility and reduced muscle tension.', '45551201', '45551201-Dynamic-90-90-Hip-Twist_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Rotate your torso through the movement pattern for Dynamic 90 90 Hip Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Dynamic 90 90 Hip Twist. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Dynamic 90 90 Hip Twist', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5cd0b424-9a7f-4985-a203-b07499593214', 'Kneeling Leg Half Circle', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build leg strength with this movement movement focusing on your delts. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '46931201', '46931201-Kneeling-Leg-Half-Circle-(male)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Set up in the starting position for Kneeling Leg Half Circle. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Kneeling Leg Half Circle', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5cd51a04-a0f0-41a3-9e9c-2cbb1ddb857d', 'Wrist Curl (Barbell)', 'Arms', 'Barbell', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. The forearms assist throughout the movement, making this a well-rounded exercise. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '1251201', '01251201-Barbell-Wrist-Curl-(VERSION-2)_Forearms-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Grip a barbell with hands at the appropriate width for Barbell Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('5cea78bc-3c69-4f9c-aa7a-186038e33b57', 'Plank Forearms Walk', 'Arms', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. You''ll also feel your shoulders, lower back working to support the movement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '104221201', '104221201-Plank-Forearms-Walk-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. Ideal for abs strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank Forearms Walk', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5cfc3cba-3966-4cda-86d5-922c4ad55603', 'Seated Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Cable resistance creates smooth, continuous muscle engagement. A strong core improves posture, protects your spine, and enhances all other lifts.', '27001201', '27001201-Cable-Seated-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'crunch', 'Seated Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5d00cd4a-73f8-41f9-b5c4-fc503064cfdb', 'Side Step Walking', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Walking is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Your quads work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '96781201', '96781201-Side-Step-Walking-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Walking. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Side Step Walking', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('5d01f257-5a4f-4fb8-a294-ce8801fad87f', 'Standing Leaning Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Target your back with this stretching stretch that helps restore range of motion. The shoulders assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105961201', '105961201-Standing-Leaning-Back-Stretch_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Leaning Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'back_stretch', 'Standing Leaning Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5d02e775-59bd-4c67-9c8f-25235673fce8', 'Hack Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '26381201', '26381201-Barbell-Hack-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard', 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'hack_squat', 'Hack Squat', 'leg_press, squat, leg_extension', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('5d0e2f94-bd74-4d1e-b45f-e15d83a62a44', 'Weighted Round Arm', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Weighted Round Arm, an effective shoulder movement exercise. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '8441201', '08441201-Weighted-Round-Arm_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Set up in the starting position for Weighted Round Arm. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Weighted Round Arm', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5d140b4e-bd1f-42ba-988c-ad36a0c2c968', 'Side Shuffle Leg Side Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '66691201', '66691201-Side-Shuffle-Leg-Side-Lift-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Set up in the starting position for Side Shuffle Leg Side Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Side Shuffle Leg Side Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5d161625-3ea1-4f99-98c1-746db3d73f4e', 'Kneeling Side Plank Twist', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{}'::text[], 'Build rotational power and define your waistline with the Kneeling Side Plank Twist. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '71221201', '71221201-Kneeling-Side-Plank-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Kneeling Side Plank Twist', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('5d23814a-6072-4597-8bab-494304f92edd', 'Oblique Rollout (TRX)', 'Core', 'TRX', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your lats, shoulders working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. A strong core improves posture, protects your spine, and enhances all other lifts.', '11221201', '11221201-Suspender-Oblique-Rollout-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Oblique Rollout. 2. Set up in the starting position for Suspender Oblique Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'ab_rollout', 'Suspender Oblique Rollout', 'plank, crunch, dead_bug', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5d2c1d52-0172-4da6-b812-0ad4dae511e6', 'Marching On Spot Shoulders Rotation', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Marching On Spot Shoulders Rotation is a cardiovascular exercise that improves endurance and heart health. You''ll also feel your hip flexors working to support the movement. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '98511201', '98511201-Marching-On-Spot-Shoulders-Rotation-(male)_Cardio_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Rotate your torso through the movement pattern for Marching On Spot Shoulders Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'marching', 'Marching On Spot Shoulders Rotation', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('5d2eb2f2-72dc-4b4b-a7a8-4963dc74a5d3', 'Squat Mobility Side Bend', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat Mobility Side Bend provides a deep stretch for your quads, ideal for recovery and mobility work. The abs assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85701201', '85701201-Squat-Mobility-Side-Bend-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 73, 2, 6, FALSE, TRUE, 'side_bend', 'Squat Mobility Side Bend', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5d4ae3f8-15d4-4d79-9403-8ffca1f859c2', 'Front Raise Shoulders Press Combo (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This pressing exercise works your front delts for improved shoulder strength and aesthetics. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '106471201', '106471201-Dumbbell-Front-Raise-Shoulders-Press-Combo-(male).mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Front Raise Shoulders Press Combo. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise Shoulders Press Combo', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5d4fc118-cac3-461a-b0ac-cce7ebf13dee', 'Hanging Front Hold (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'The Hanging Front Lever Hold is a core movement exercise that primarily targets your abs. The hip flexors, grip assist throughout the movement, making this a well-rounded exercise. The hanging position challenges your grip while targeting the primary muscles. The machine guides your movement path for safer, more controlled repetitions. A strong core improves posture, protects your spine, and enhances all other lifts.', '90451201', '90451201-Hanging-Front-Lever-Hold-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Hanging Front Lever Hold. 2. Grip the bar and hang with arms fully extended, engaging your shoulders. 3. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'front_lever', 'Hanging Front Lever Hold', 'pull_up, lat_pulldown, grip_training', FALSE, 'pull_up_bar', TRUE, 3, 90, 4, 80, 75, 20, 88),
('5daa441b-8718-4647-87d9-d42f1876999b', 'Triceps Pushdown - SZ Bar (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pushing exercise for bigger arms. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '90041201', '90041201-Cable-Triceps-Pushdown-(SZ-bar)-(female)_Upper-arm.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Triceps Pushdown. 2. Set up in the starting position for Cable Triceps Pushdown. 3. Execute the movement with proper form, focusing on your triceps. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Triceps Pushdown', 'tricep_extension, close_grip_bench, dip', TRUE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5dc28475-4435-4f6d-a375-8b82bd37d652', 'Arm Thruster (Kettlebell) - Alternating', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Build total body strength and coordination with this multi-joint thrusting movement. You''ll also feel your quads, shoulders working to support the movement. Kettlebells are excellent for building functional, real-world strength. Compound movements like this develop coordination, power, and overall fitness.', '96921201', '96921201-Kettlebell-Alternating-Arm-Thruster_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Select an appropriately weighted kettlebell for Kettlebell Alternating Arm Thruster. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Alternate between sides/arms/legs with each repetition. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'thruster', 'Arm Thruster - Alternating', 'front_squat, shoulder_press, clean', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('5dc38670-5190-4793-b50e-b0c50902e15e', 'Box Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. Secondary activation of your quads, calves provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '49651201', '49651201-Jump-Box-(male)_Plyometrics-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Jump Box. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jump Box', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5dc95cfb-1ee1-4a8a-b0a5-062861389c87', 'Leg Press (Smith Machine)', 'Legs', 'Smith Machine', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pressing movement emphasizes your quadriceps for stronger, more powerful legs. The glutes assist throughout the movement, making this a well-rounded exercise. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '36191201', '36191201-Smith-Leg-Press-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Leg Press. 2. Position your feet on the platform and release the safety. 3. Lower the weight by bending your knees, then press back up powerfully. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 88, 7, 9, TRUE, FALSE, 'leg_press', 'Smith Leg Press', 'Leg Press', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('5dcb47aa-5a1b-4ee5-b0f0-99f6ec38f6b0', 'Walking Side Step Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Elevate your training with this rowing exercise that develops speed, power, and coordination. Your quads work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '90591201', '90591201-Walking-Side-Step-Row-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'walking', 'Walking Side Step Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e020abc-0969-4c61-b2a4-e7e276a96563', 'Plank Jack (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Resistance Band Plank Jack is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Core strength is foundational for athletic performance and injury prevention.', '72101201', '72101201-Resistance-Band-Plank-Jack-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Plank Jack. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 75, 9, 8, TRUE, TRUE, 'plank', 'Plank Jack', 'side_plank, dead_bug, hollow_hold', FALSE, 'band', FALSE, 3, 60, 4, 60, 85, 90, 50),
('5e02d7b5-b49c-45cc-9e92-cef8c97a5f25', 'Kneeling Hip Flexor Sagital', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{}'::text[], 'This stretch specifically works on your hip flexors, promoting flexibility and reducing muscle tightness. Kneeling helps eliminate lower body momentum from the movement. Flexibility work like this enhances performance and prevents stiffness.', '78621201', '78621201-Kneeling-Hip-Flexor-Sagital-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Sagital. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Sagital', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e05060b-628f-4210-914d-323dfee75b74', 'Seated Uppercut (Chair)', 'Full Body', 'Chair', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. You''ll also feel your shoulders, core working to support the movement. The seated position helps isolate the target muscles by removing momentum. Develops fast-twitch muscle fibers for quicker, more powerful movements. Can be modified for beginners or progressed for advanced athletes.', '72631201', '72631201-Sitting-Uppercut-on-Chair-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'boxing', 'Seated Uppercut On Chair', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e0c936a-f7cc-45e5-8ef8-87ef9179a8fa', 'Standing Hip Frontal Rotation Arm Sways', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Elevate your training with this rotation exercise that develops speed, power, and coordination. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '60821201', '60821201-Standing-Hip-Frontal-Rotation-Arm-Sways-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation Arm Sways. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Arm Sways', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e1a53c4-a239-43f1-8a6e-894f109413f9', 'Lying Prone Shoulder Extension', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This extension exercise works your delts for improved shoulder strength and aesthetics. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '87161201', '87161201-Lyine-Prone-Shoulder-Extension-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Lie face down with your body in a straight line. 2. Extend through the target joint(s) for Lying Prone Shoulder Extension. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shoulder_exercise', 'Lying Prone Shoulder Extension', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5e1e5bcf-25cf-4fd1-85df-b8c1d8ba7698', 'Standing Front Clap Back Clap', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your front delts for improved shoulder strength and aesthetics. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '65641201', '65641201-Standing-Front-Clap-Back-Clap-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Front Clap Back Clap. 3. Execute the movement with proper form, focusing on your front delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Front Clap Back Clap', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e279953-a7e7-40de-9fa6-957651fbd159', 'Side Step Overhead Front Raise', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Side Step Overhead Front Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. Great for improving athletic performance, burning calories, and building conditioning.', '68961201', '68961201-Side-Step-Overhead-Front-Raise-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'front_raise', 'Side Step Overhead Front Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5e2e6153-0306-4e99-9863-652b2fdf14f7', 'Reverse Lunge High Knee', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '63891201', '63891201-Bodyweight-Reverse-Lunge-High-Knee-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. A solid choice for legs day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge High Knee', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5e35b1f2-a6d4-4db6-a10c-3a96e8ddb237', 'Pike Pushup (Stability Ball)', 'Chest', 'Stability Ball', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Exercise Ball Pike Pushup, an effective pushing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12961201', '12961201-Exercise-Ball-Pike-Pushup_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Position the stability ball as needed for Exercise Ball Pike Pushup. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Exercise Ball Pike Pushup', 'bench_press, chest_fly, dip', TRUE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e39a4a4-94f7-4393-8016-b0dbe1b32aff', 'Side Step Jump Side Bend - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Alternate Side Step Jump Side Bend builds reactive power and improves conditioning. The abs assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '87941201', '87941201-Alternate-Side-Step-Jump-Side-Bend-(male)_Plyometr.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up a box or step platform at the appropriate height. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'side_bend', 'Side Step Jump Side Bend - Alternating', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5e3e3a48-33b2-4685-b8b7-b5e2429a9b94', 'Weighted Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Crunch is a core crunching exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '25401201', '25401201-Weighted-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Weighted Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5e451656-1a70-40f7-a549-57a50f4e5389', 'Standing Behind Neck Press', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Standing Behind Neck Press, an effective shoulder pressing exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '7881201', '07881201-Standing-Behind-Neck-Press_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Stand tall with your feet firmly planted. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'neck_exercise', 'Standing Behind Neck Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e699200-32f3-472c-9125-7aa9b05f1505', 'Olympic (Barbell) Triceps Extension', 'Arms', 'Barbell', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Olympic Barbell Triceps Extension targets your triceps through a extension motion. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements.', '6371201', '06371201-Olympic-Barbell-Triceps-Extension_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Grip a barbell with hands at the appropriate width for Olympic Barbell Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Olympic Triceps Extension', 'Olympic Triceps Extension', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('5e6fe39c-8498-4428-aa8d-9758aeb6a063', 'Reverse Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. This variation is excellent for building mind-muscle connection.', '6711201', '06711201-Reverse-Crunch-(female)_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Lift your hips off the floor by contracting your lower abs. 2. Bring your knees toward your chest, then lower with control. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Reverse Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5e7ceafc-ccd0-4628-ba33-176bc871f2ae', 'Cross Body Punch Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Secondary activation of your shoulders, core provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities. Maintain proper breathing - exhale during the effort phase.', '55851201', '55851201-Cross-Body-Punch-Jack-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set up in the starting position for Cross Body Punch Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shoulder_stretch', 'Cross Body Punch Jack', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5e80f308-fc26-4af8-a744-b90759f0b80a', 'Seated Leaning Back Hundreds (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build stronger shoulders with this movement movement focusing on your core. The seated position helps isolate the target muscles by removing momentum. Strong shoulders improve overhead strength and support nearly all upper body movements.', '104941201', '104941201-Seated-Leaning-Back-Hundreds-on-Chair-(male)_Shou.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Leaning Back Hundreds On Chair', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5e96b909-3bbf-4e3d-85a1-fded2aeb7f02', 'Side To Side Rotational Arm Extension', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Core","Shoulders"}'::text[], 'Elevate your training with this extension exercise that develops speed, power, and coordination. Secondary activation of your core, shoulders provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '89231201', '89231201-Side-to-Side-Rotational-Arm-Extension-(female)_Ply.mp4', 'female', FALSE, '2025-12-03 23:26:37.429219+00', '1. Extend through the target joint(s) for Side To Side Rotational Arm Extension. 2. Set up in the starting position for Side To Side Rotational Arm Extension. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'woodchop', 'Side To Side Rotational Arm Extension', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5e9ec1aa-e335-4a10-9934-bff1c6ec33a3', 'Handstand Hold (Against Wall)', 'Shoulders', 'Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. Shoulder development enhances both performance and upper body aesthetics.', '65451201', '65451201-Handstand-Hold-on-Wall-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Position yourself at the appropriate distance from a wall. 2. Hold the position for the prescribed time, maintaining tension. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'yoga', 'Handstand Hold On Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5ea04b44-dd9e-4cea-b779-2438ab08ce0e', 'Butterfly Yoga Pose', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Butterfly Yoga Pose is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Include this in your routine for better mobility and reduced muscle tension.', '45081201', '45081201-Butterfly-Yoga-Pose-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. Start with lighter weight to perfect your form. A solid choice for stretching day.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'groin_stretch', 'Butterfly Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5eb187f4-bd89-4d29-9833-93a3d94272dc', 'Lying Elbow To Knee', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Elbow To Knee is a core movement exercise that primarily targets your abs. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '70831201', '70831201-Lying-Elbow-to-Knee-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Elbow To Knee. 2. Set up in the starting position for Lying Elbow To Knee. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Elbow To Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5eb7c563-663b-4ca4-8ae4-b64ca848901a', 'Landmine Kneeling Single Arm Shoulder Press (Landmine)', 'Shoulders', 'Landmine Attachment, Barbell', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Your triceps work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. Shoulder development enhances both performance and upper body aesthetics.', '98241201', '98241201-Landmine-Kneeling-Single-Arm-Shoulder-Press-(male).mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'shoulder_press', 'Landmine Kneeling Single Arm Shoulder Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('5eb9c444-f3ad-43f5-a885-405cd656d822', 'T-Bar Row (Plate Loaded Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '28851201', '28851201-Lever-T-bar-Row-(plate-loaded)-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever T Bar Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 't_bar_row', 'Lever T Bar Row', 'bent_over_row, lat_pulldown, deadlift', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('5ebedb11-b493-4672-8551-e5baaa4ab6ef', 'Elbow To Knee Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your abs provides additional muscle engagement. Regular cardio training builds the aerobic base for better overall fitness.', '4421201', '04421201-Elbow-To-Knee-Twists-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Rotate your torso through the movement pattern for Elbow To Knee Twists. 2. Control the rotation in both directions—avoid using momentum. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Elbow To Knee Twist', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5ec3134c-71fb-4ad5-ae0b-c28d749ac567', 'Seated Legs Extended To Butterfly Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your adductors, promoting flexibility and reducing muscle tightness. Your hips work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '96731201', '96731201-Sitting-Legs-Extended-to-Butterfly-Stretch-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'groin_stretch', 'Seated Legs Extended To Butterfly Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('5ec5e713-a451-40fa-bcbf-b49fc48b921b', 'Basketball Shot Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Basketball Shot Jump builds reactive power and improves conditioning. Your quads, calves work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '47091201', '47091201-Basketball-Shot-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Basketball Shot Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Basketball Shot Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5ec6c61b-1400-4a3f-b4fa-0869954b84f8', 'Seated Half Circle Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Dumbbell Seated Half Circle Front Raise, an effective shoulder raising exercise. Being seated provides stability, allowing you to focus on the working muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '105141201', '105141201-Dumbbell-Seated-Half-Circle-Front-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Half Circle Front Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'front_raise', 'Seated Half Circle Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5ec6f631-ec60-445e-8c2b-d308ae24151c', 'Rotator Cuff Warm Up', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your rotator cuff with the Rotator Cuff Warm Up, an effective shoulder movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '54561201', '54561201-Rotator-Cuff-Warm-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Set up in the starting position for Rotator Cuff Warm Up. 2. Execute the movement with proper form, focusing on your rotator cuff. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Rotator Cuff Warm Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5eca9676-7899-4b35-b564-12b3f3e26aca', 'Overhead Press - Reverse Grip (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Secondary activation of your triceps provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Strong shoulders improve overhead strength and support nearly all upper body movements.', '93951201', '93951201-Barbell-Reverse-Grip-Overhead-Press-(male)_Shoulde.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Grip a barbell with hands at the appropriate width for Barbell Reverse Grip Overhead Press. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'shoulder_press', 'Overhead Press - Reverse Grip', 'Overhead Press - Reverse Grip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('5ed15cef-b103-4c6c-a3d7-f2ffad52a690', 'Front Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Core"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '29671201', '29671201-Dumbbell-Front-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:32.735372+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'front_squat', 'Front Squat', 'squat, leg_press, leg_extension, goblet_squat', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('5eefef0a-9317-44a1-b407-b9586a4c5e0f', 'Side To Side Jump Over Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity jumping exercise that challenges your entire body. Secondary activation of your quads, calves provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '107321201', '107321201-Side-to-Side-Jump-over-StepBox-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side To Side Jump Over Stepbox. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Side To Side Jump Over Stepbox', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5f1652ab-ed34-4f54-8403-d404e0559f91', 'Ring Back Lever (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Ring Back Lever, focusing on your abs. The machine guides your movement path for safer, more controlled repetitions. Core strength is foundational for athletic performance and injury prevention.', '75151201', '75151201-Ring-Back-Lever-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Ring Back Lever. 2. Set up in the starting position for Ring Back Lever. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'back_exercise', 'Ring Back Lever', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 80, 75, 20, 88),
('5f31dacb-0aa9-4ea9-83aa-9f0729e4af57', 'Seated Overhead Press (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Barbell Seated Overhead Press, an effective shoulder pressing exercise. Your triceps work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Using a barbell provides stability for progressive overload. Strong shoulders improve overhead strength and support nearly all upper body movements.', '26041201', '26041201-Barbell-Seated-Overhead-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Overhead Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Seated', NULL, 'Overhand', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Seated Overhead Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('5f3bd028-3411-4afd-8db8-39dbd6e0c8f6', 'Seated Thumbs Up Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Thumbs Up Pulse is a movement exercise that develops back strength and muscle. Being seated provides stability, allowing you to focus on the working muscles. Back development is crucial for pulling strength and overall upper body function.', '87301201', '87301201-Seated-Thumbs-Up-Pulse-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Seated Thumbs Up Pulse', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5f42b91f-50fb-4b86-8e20-518110426bff', 'Leg Pull Side', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this pulling stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness.', '28481201', '28481201-Leg-Pull-Side_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Move into the stretch position for Leg Pull Side. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Leg Pull Side', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5f4bcda4-389d-4d36-b697-82a2dfc48b84', 'Stiff Leg Deadlift (Dumbbell)', 'Legs', 'Dumbbells', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'This hip hinge exercise engages your abs for improved core stability and strength. You''ll also feel your glutes, lower back working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Core strength is foundational for athletic performance and injury prevention.', '4321201', '04321201-Dumbbell-Stiff-Leg-Deadlift_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Stiff Leg Deadlift. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Stiff Leg Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('5f514ba1-2672-405d-87e2-279d68608a08', 'Bicep Clutch - Pullup (TRX)', 'Arms', 'TRX', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This movement exercise focuses on your biceps for improved arm size and strength. Suspension training adds instability, increasing core activation throughout. Dedicated arm training builds both strength and muscular definition.', '11091201', '11091201-Suspender-Biceps-Clutch-(female)_Upper-arms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Biceps Clutch. 2. Set up in the starting position for Suspender Biceps Clutch. 3. Execute the movement with proper form, focusing on your biceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'arm_exercise', 'Suspender Biceps Clutch', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('5f524e68-cd9c-45f3-a317-65d374544565', 'Deep Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. Control the negative portion for maximum muscle engagement.', '28231201', '28231201-Deep-Push-Up-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Deep Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5f615eaf-bb45-47bb-aaad-05ec482526bb', 'Upright Shoulder External Rotation (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Dumbbell Upright Shoulder External Rotation is a rotation exercise that develops back strength and muscle. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '8641201', '08641201-Dumbbell-Upright-Shoulder-External-Rotation_Back.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Upright Shoulder External Rotation. 2. Rotate your torso through the movement pattern for Dumbbell Upright Shoulder External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'external_rotation', 'Upright Shoulder External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('5f656cd3-5906-49fc-9efb-7c8852dcbcd1', 'Elevated Single Leg Hip Thrust (Step Platform)', 'Legs', 'Step Platform', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '49021201', '49021201-Elevated-Single-Leg-Hip-Thrust-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'hip_thrust', 'Elevated Single Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5f657276-5728-4329-a57b-a517050aa802', 'Standing Inner Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '25801201', '25801201-Cable-Standing-Inner-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Inner Curl. 2. Begin in a standing position with good posture. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Inner Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('5f682de8-f264-4d25-9ea1-70af3e53ea0c', 'Meditation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Works well as both a primary exercise or accessory movement.', '58941201', '58941201-Meditation-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Move into the stretch position for Meditation. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Meditation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('5f73fd1d-c4a7-47bb-b7f9-6703a91ead78', 'Jumping Jack Toe Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Jumping Jack Toe Touch is an explosive exercise that combines cardiovascular training with dynamic jumping movements. Your shoulders, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '71461201', '71461201-Jumping-Jack-Toe-Touch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Set up in the starting position for Jumping Jack Toe Touch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'jumping_jack', 'Jumping Jack Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5f787f5c-6cc1-44ec-9e99-7c64540b2bc7', 'Straight Arm Crunch (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Dumbbell Straight Arm Crunch, focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Core strength is foundational for athletic performance and injury prevention.', '42481201', '42481201-Dumbbell-Straight-Arm-Crunch_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Straight Arm Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'crunch', 'Straight Arm Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('5f81a880-b2ab-4d46-816c-6aacb976858f', 'Upper Chest Raise - Alternating', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build a stronger chest with this raising movement that develops pressing power. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '76001201', '76001201-Alternate-Upper-Chest-Raise-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Raise the weight in the prescribed direction for Alternate Upper Chest Raise. 2. Lower with control, maintaining tension throughout. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'lateral_raise', 'Upper Chest Raise - Alternating', 'shoulder_press, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('5f97c854-0977-423a-9c5b-7d58a67a5182', 'Kneeling Push Up Jump', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '85041201', '85041201-Kneeling-Push-Up-Jump-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. This exercise is excellent for chest development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Kneeling Push Up Jump', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('5fab6418-5e23-4883-98e9-b68f89f7bc80', 'Explosive Push Up (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Resistance Band Explosive Push Up is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. Resistance bands provide accommodating resistance that increases through the range of motion. A well-developed chest contributes to upper body strength and aesthetics.', '106501201', '106501201-Resistance-Band-Explosive-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Secure the resistance band appropriately for Resistance Band Explosive Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Perform the concentric (lifting) phase explosively with maximum effort. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'push_up', 'Explosive Push Up', 'bench_press, chest_fly, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('5fb6c26d-9725-4e9b-b79c-2eb323db5e96', 'Front Chest Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Strong legs are the foundation for athletic performance and functional fitness.', '391201', '00391201-Barbell-Front-Chest-Squat_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Front Chest Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Front Chest Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('5fccd879-cfcf-4451-9fca-b43d0ea10551', 'Arnold Press (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Kettlebell Arnold Press is a pressing exercise that targets your delts for shoulder development. Secondary activation of your triceps provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '5231201', '05231201-Kettlebell-Arnold-Press_Shoulder.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Select an appropriately weighted kettlebell for Kettlebell Arnold Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'shoulder_press', 'Arnold Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('5fd6b28f-7685-4246-9a8e-c67c80426892', 'Hip Roll Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Excellent for pre-exhausting the target muscle before compound lifts.', '46491201', '46491201-Hip-Roll-Plank-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Ensure full range of motion on each rep. This variation specifically emphasizes the abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Hip Roll Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('5fdb7675-394e-47de-8457-cab8ce43f8fd', 'Cross Abduction (Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. You''ll also feel your shoulders, core working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Plyometric training builds explosive power that transfers to sports and daily activities.', '41361201', '41361201-Band-Cross-Abduction_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Secure the resistance band appropriately for Band Cross Abduction. 2. Set up in the starting position for Band Cross Abduction. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Cross Abduction', 'plank, crunch, leg_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('5fe69c1b-0239-4d0f-91b7-5c45b9c1131e', '90 Degrees External Rotation (Resistance Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Resistance Band 90 Degrees External Rotation is a rotation exercise that targets your rotator cuff for shoulder development. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '91421201', '91421201-Resistance-Band-90-degrees-External-Rotation-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band 90 Degrees External Rotation. 2. Rotate your torso through the movement pattern for Resistance Band 90 Degrees External Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'external_rotation', '90 Degrees External Rotation', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('5fef3099-427a-4358-9612-cd632f4eda8f', 'Lying Bench Side Oblique Crunch (Plate)', 'Core', 'Weight Plate', '{"Abs"}'::text[], '{}'::text[], 'The Weighted Plate Lying Bench Side Oblique Crunch targets your obliques through a crunching motion, building rotational core strength. You''ll also feel your abs working to support the movement. Performing this lying down removes momentum for stricter form. Building core stability helps with everything from heavy deadlifts to daily activities.', '104311201', '104311201-Weighted-Plate-Lying-Bench-Side-Oblique-Crunch-(m.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Lie on your side with your body aligned. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Weighted Plate Lying Bench Side Oblique Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'plate', FALSE, 3, 60, 2, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('60131fa0-2d25-4a74-9c6f-3bcd77523954', 'Rear Kick (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This kicking exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '99041201', '99041201-Lever-Pure-Rear-Kick-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Pure Rear Kick. 2. Set up in the starting position for Lever Pure Rear Kick. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Lever Pure Rear Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('601a2b23-7524-4914-8e94-d5bd9572f454', 'Seated Hip Mobilization Circle (Stability Ball)', 'Shoulders', 'Stability Ball', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. The seated position helps isolate the target muscles by removing momentum. The stability ball adds an instability challenge that activates more stabilizer muscles. Shoulder development enhances both performance and upper body aesthetics.', '98291201', '98291201-Sitting-Hip-Mobilization-Circle-on-Exercise-Ball-(.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Position the stability ball as needed for Seated Hip Mobilization Circle On Exercise Ball (. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'mobility', 'Seated Hip Mobilization Circle On Exercise Ball (', 'hip_thrust, lunge, squat', FALSE, 'stability_ball', TRUE, 1, 30, 2, 70, 88, 95, 65),
('601a67dd-ccac-429a-a59b-7815b27ff69f', 'Criss Cross Knee Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Criss Cross Knee Tuck is an explosive exercise that combines cardiovascular training with dynamic movement movements. You''ll also feel your shoulders, core working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '71481201', '71481201-Criss-Cross-Knee-Tuck-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Set up in the starting position for Criss Cross Knee Tuck. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Criss Cross Knee Tuck', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('601bd346-f3ab-430e-84c1-cfc5bf72cc7e', 'Lying Triceps Extension - Close Grip (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Barbell Lying Close Grip Triceps Extension targets your triceps through a extension motion. The lying position provides back support and helps isolate the target muscles. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '561201', '00561201-Barbell-Lying-Close-Grip-Triceps-Extension_Upper-A.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lying Close Grip Triceps Extension. 2. Lie down in the appropriate position for Barbell Lying Close Grip Triceps Extension. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension - Close Grip', 'Lying Triceps Extension - Close Grip', TRUE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('601e854b-4a84-4847-98a7-08e771dcc5cc', 'Front Squat - Clean Grip (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads","Glutes","Core"}'::text[], '{}'::text[], 'The Smith Front Squat (clean Grip) is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Machine exercises are great for isolating muscles and training to failure safely. Lower body strength improves everything from walking to heavy compound lifts.', '28241201', '28241201-Smith-Front-Squat-(Clean-Grip)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'front_squat', 'Smith Front Squat', 'Front Squat', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('602487db-c80b-48af-a387-c5b2a3ada785', 'Seated Good Morning (Barbell)', 'Back', 'Barbell, Flat Bench', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'Strengthen the back of your thighs with this movement exercise. Your glutes, lower back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '901201', '00901201-Barbell-Seated-Good-morning_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Grip a barbell with hands at the appropriate width for Barbell Seated Good Morning. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Pull', 'Pull', 'Compound', 'Bilateral', NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, 'Overhand', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 64, 7, 8, TRUE, TRUE, 'back_extension', 'Seated Good Morning', 'romanian_deadlift, back_extension, hip_thrust', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('6030b96f-7fbd-4cb0-9109-2c87e62d0c7d', 'Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '6121201', '06121201-Lunge-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form. Works well for quads activation.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('603b7516-4dba-4361-8ed8-2db0a802f7a8', 'Pin Squat (Barbell)', 'Legs', 'Barbell, Power Rack', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts. This variation is excellent for building mind-muscle connection.', '57011201', '57011201-Barbell-Pin-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Pin Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Pin Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('603bfd0b-f4bd-4e03-8e3c-f126014e7e02', 'Split Squat With Low Box', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '72421201', '72421201-Split-Squat-with-Low-Box_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Split Squat With Low Box', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('603db727-2bed-43cf-8a60-c3beffa2bd46', 'Lateral Step Up (Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this stepping movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '5661201', '05661201-Lateral-Step-up-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Set up a box or step platform at the appropriate height. 2. Step one foot onto the elevated surface. 3. Drive through that foot to lift your body up onto the platform. 4. Step back down with control and repeat. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout. This exercise is excellent for quads development.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'step_up', 'Lateral Step Up', 'lunge, split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6043fca1-67b5-462b-b63b-f18a7c7a0319', 'Rear Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts. Keep your core engaged throughout the exercise.', '3811201', '03811201-Dumbbell-Rear-Lunge_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Rear Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('6045c83f-5916-4e73-9372-0dd0d1ccbf36', 'Patrick Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this stepping movement focusing on your full body. Your quads work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness. Quality repetitions are more important than quantity.', '96011201', '96011201-Bodyweight-Patrick-Step-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Bodyweight Patrick Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Patrick Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6050f160-49df-43f3-83db-6f5e40be7170', 'Side Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '12151201', '12151201-Dumbbell-Side-Lunge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('605ec30d-b983-4ae8-8e59-3f27ad9213f7', 'Standing Opposite Straight Arm Clasp (Right Over Left)', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build total body strength and coordination with this multi-joint movement movement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Full body exercises are time-efficient and build functional, real-world strength. A staple exercise that belongs in most training programs. Consistency with this movement will yield noticeable results.', '94141201', '94141201-Standing-Opposite-Straight-Arm-Clasp-(right-over-l.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Opposite Straight Arm Clasp (right Over L. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Opposite Straight Arm Clasp (right Over L', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('608a268c-8a6f-41aa-968b-d6daf00b1403', 'Assisted Single Arm Pull Up (Resistance Band)', 'Back', 'Resistance Band, Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. Your biceps, upper back work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '106601201', '106601201-Resistance-Band-Assisted-Single-Arm-Pull-up-(male.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Secure the resistance band appropriately for Resistance Band Assisted Single Arm Pull Up. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Single Arm Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('608c04c2-d0d5-4237-b3fd-75aae54f51d5', 'Push Up To Side Plank (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. Suspension training adds instability, increasing core activation throughout. A well-developed chest contributes to upper body strength and aesthetics.', '95021201', '95021201-Suspender-Push-Up-to-Side-Plank_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Push Up To Side Plank. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'side_plank', 'Suspender Push Up To Side Plank', 'bench_press, chest_fly, dip, tricep_pushdown', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('608e9ea1-5a54-4307-87a4-9e4e402d78d5', 'Hyperextension (Plate, Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension exercise isolates your glutes for improved hip strength and power. Secondary activation of your hamstrings, lower back provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '12341201', '12341201-Plate-Hyperextension_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Plate Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('60cb1bd0-3154-4404-afb1-ee1724adf262', 'Jackknife Sit Up (Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hamstrings"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '9811201', '09811201-Band-Jackknife-Sit-Up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Secure the resistance band appropriately for Band Jackknife Sit Up. 2. Set up in the starting position for Band Jackknife Sit Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 75, 9, 8, TRUE, TRUE, 'v_up', 'Jackknife Sit Up', 'crunch, leg_raise, plank', FALSE, 'band', FALSE, 3, 60, 4, 60, 85, 90, 50),
('60d2237e-9bbd-4f47-9527-15c49ec3e08d', 'Kneeling Glute Kickback (Cable)', 'Legs', 'Cables', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'Develop your posterior chain with this kicking movement that emphasizes the glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. Cables provide constant tension throughout the full range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '75891201', '75891201-Cable-Kneeling-Glute-Kickback-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Glute Kickback. 2. Kneel on the floor (use a pad for comfort if needed). 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'glute_kickback', 'Kneeling Glute Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('60d2dbba-1241-4ad9-8577-a21ec0914d25', 'Arms Curl Knee Drive', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Elevate your training with this curling exercise that develops speed, power, and coordination. You''ll also feel your forearms working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '69281201', '69281201-Arms-Curl-Knee-Drive-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Keep your elbows in a fixed position throughout the movement. 2. Curl the weight up by contracting your biceps, squeezing at the top. 3. Lower with control, resisting the weight on the way down. 4. Complete all reps with control before resting. Ensure full range of motion on each rep.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'knee_drive', 'Arms Curl Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('60f517b1-fee3-48dc-bdca-39327bfe0cd1', 'Incline Y Raise (Kettlebell)', 'Shoulders', 'Kettlebell, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Target your delts with the Kettlebell Incline Y Raise, an effective shoulder raising exercise. The upper back assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. Kettlebells are excellent for building functional, real-world strength. Shoulder development enhances both performance and upper body aesthetics.', '68391201', '68391201-Kettlebell-Incline-Y-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Y Raise. 2. Raise the weight in the prescribed direction for Kettlebell Incline Y Raise. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 81, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Y Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('60f52980-3cae-41b7-8408-25eafc94696a', 'Overhead Throw (Medicine Ball)', 'Back', 'Medicine Ball', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'A challenging plyometric exercise, the Medicine Ball Overhead Throw builds reactive power and improves conditioning. You''ll also feel your biceps, rear delts working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '42431201', '42431201-Medicine-Ball-Overhead-Throw_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Overhead Throw. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Medicine Ball Overhead Throw', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('60fccbbf-db4c-4355-bd66-21222f639f06', 'Standing Hand Out Cross Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'The Standing Hand Out Cross Kick is an explosive exercise that combines cardiovascular training with dynamic kicking movements. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '89131201', '89131201-Standing-Hand-Out-Cross-Kick-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Hand Out Cross Kick. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Hand Out Cross Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('611ed3da-f581-424a-bc96-47e3aa203df9', 'Russian Twist Boat Row (Dumbbell)', 'Back', 'Dumbbells', '{"Obliques"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing movement focuses on your obliques for a complete core workout. Your abs work as secondary movers, adding to the training stimulus. Using dumbbells requires more stabilization than barbell variations. Building core stability helps with everything from heavy deadlifts to daily activities.', '72451201', '72451201-Dumbbell-Russian-Twist-Boat-Row-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Russian Twist Boat Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'russian_twist', 'Russian Twist Boat Row', 'crunch, plank, leg_raise, wood_chop', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('61217f19-c791-45ef-af50-418ba30e9d41', 'Bridge Straight Leg Raise', 'Legs', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hamstrings"}'::text[], 'This raising exercise isolates your glutes for improved hip strength and power. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '84951201', '84951201-Bridge-Straight-Leg-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Bridge Straight Leg Raise', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('61350c69-27d3-490e-8434-c8780efe602f', 'Side Step Bend - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Alternate Side Step Bend builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '85171201', '85171201-Alternate-Side-Step-Bend-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Set up a box or step platform at the appropriate height. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Bend - Alternating', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6145985e-6b2e-4235-b1e6-c74f6ba4a867', 'Bent Over Row - Single Arm - Neutral Grip (Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. The machine guides your movement path for safer, more controlled repetitions. A strong back improves posture, prevents injury, and balances pressing movements.', '65151201', '65151201-Lever-Bent-Over-Single-Arm-Neutral-Grip-Row-(with-.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Single Arm Neutral Grip Row (with. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps on one side, then switch to the other side. 8. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 73, 7, 9, TRUE, FALSE, 'arm_exercise', 'Lever Bent Over Single Arm Neutral Grip Row (with', 'Lever Bent Over Single Arm Row (with - Neutral Grip', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('61494a7c-fc72-4f24-b148-af8790acdc4d', 'Forward Backward Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '86451201', '86451201-Barbell-Forward-Backward-Lunge-(VERSION-2)-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Grip a barbell with hands at the appropriate width for Barbell Forward Backward Lunge. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Forward Backward Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('615916f3-c166-441d-a177-d0726527c978', 'Overhead Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Barbell Overhead Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '691201', '00691201-Barbell-Overhead-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Overhead Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Overhead Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('615ca083-e0b5-457d-9475-dc72a8172469', 'Kneeling Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Kneeling Plank, focusing on your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '49961201', '49961201-Kneeling-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Kneeling Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('615d8a72-28f3-4b41-985a-14a6a7d8428c', 'Row And Stepover', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'A challenging plyometric exercise, the Row And Stepover builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '82771201', '82771201-Row-and-Stepover-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. An effective movement for your plyometrics routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Row And Stepover', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('61612406-edfa-4330-bfc3-665195b54b74', 'Kneeling Push Up To Hovering Table Top (Gymnastic Rings)', 'Chest', 'Gymnastic Rings', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '87631201', '87631201-Kneeling-Push-Up-to-Hovering-Table-Top-(female)_Ch.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Push Up To Hovering Table Top', 'bench_press, chest_fly, dip', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('61777e68-fc54-4c64-a778-c711606bbded', 'Bicycle Crunch Floor Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Bicycle Crunch Floor Touch is a core crunching exercise that primarily targets your abs. Secondary activation of your abs provides additional muscle engagement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '105811201', '105811201-Bicycle-Crunch-Floor-Touch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Position yourself on the floor for Bicycle Crunch Floor Touch. 2. Bring one knee toward chest while extending the other leg. 3. Rotate to bring opposite elbow toward the bent knee. 4. Alternate sides in a pedaling motion. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'cycling', 'Bicycle Crunch Floor Touch', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('617fa283-1046-4241-9aac-3ed0d72c8cc2', 'Seated Floor Floating Heels Together Abductor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Floor Floating Heels Together Abductor is a lower body movement exercise that targets your hip abductors. Secondary activation of your glutes provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '96401201', '96401201-Sitting-Floor-Floating-Heels-Together-Abductor-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself on the floor for Seated Floor Floating Heels Together Abductor. 2. Sit on the floor with your legs positioned as required. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'hip_abduction', 'Seated Floor Floating Heels Together Abductor', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6185e195-6db7-4714-87fc-91430f6dff4a', 'Bicep Curl (Dumbbell) - Alternating', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '2851201', '02851201-Dumbbell-Alternate-Biceps-Curl_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Alternate Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'bicep_curl', 'Biceps Curl - Alternating', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('618e6b7b-8e0f-4403-bc4d-278dceb302ca', 'Side Bear Crawl', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. This variation is excellent for building mind-muscle connection.', '39651201', '39651201-Side-Bear-Crawl_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Set up in the starting position for Side Bear Crawl. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Cardio', 50, 7, 8, TRUE, TRUE, 'bear_crawl', 'Side Bear Crawl', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('6195fedb-8ff5-4a2c-a654-54ce30e613ac', 'Standing Bend Toe Touch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Bend Alternating Toe Touch builds reactive power and improves conditioning. The hip flexors assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '101881201', '101881201-Standing-Bend-Alternating-Toe-Touch-(female)_Plyo.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'toe_touch', 'Standing Bend Toe Touch - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('61a22216-9796-413a-954f-ce9325bbf314', 'Standing Single Arm Circling', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '32571201', '32571201-Standing-One-Arm-Circling-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Complete all reps on one side, then switch to the other side. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Single Arm Circling', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('61a8c2f1-0f51-4604-8d4e-96646c217f6f', 'Balance Rear Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Balance Rear Lunge is a lunging exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '73451201', '73451201-Balance-Rear-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection. An effective movement for your legs routine.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'balance', 'Balance Rear Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('61adb2d5-363b-49ea-96fc-26cd493610e3', 'Standing Concentration Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '4181201', '04181201-Dumbbell-Standing-Concentration-Curl_Upper-Arms-FI.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Concentration Curl. 2. Stand tall with your feet firmly planted. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'concentration_curl', 'Standing Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('61b43a29-0504-43ca-9650-16e89632d63f', 'Wide Front Elbow Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Wide Front Elbow Plank is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '66581201', '66581201-Wide-Front-Elbow-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Wide Front Elbow Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('61bbf52f-2bb1-4109-bd13-64a7cce39860', 'Incline Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Dumbbell Incline Raise is a raising exercise that targets your delts for shoulder development. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '3251201', '03251201-Dumbbell-Incline-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Raise. 2. Raise the weight in the prescribed direction for Dumbbell Incline Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'general_exercise', 'Incline Raise', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('61c68385-e5f9-4a2f-bd7c-51b8c11c4110', 'Seated Lateral Raise (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The seated position helps isolate the target muscles by removing momentum. Kettlebells are excellent for building functional, real-world strength. Shoulder development enhances both performance and upper body aesthetics.', '68331201', '68331201-Kettlebell-Seated-Lateral-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Select an appropriately weighted kettlebell for Kettlebell Seated Lateral Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'lateral_raise', 'Seated Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
